     <hudson.model.StringParameterDefinition>\n          <name>GIT_USER</name>\n          <description>Git User</description>\n          <defaultValue>{{GIT_USER}}</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n         <hudson.model.StringParameterDefinition>\n          <name>GIT_TOKEN</name>\n          <description>Git Private token</description>\n          <defaultValue>{{GIT_TOKEN}}</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n         <hudson.model.StringParameterDefinition>\n          <name>GIT_BRANCHNAME</name>\n          <description>deploy branch name</description>\n          <defaultValue>master</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n        <hudson.model.StringParameterDefinition>\n          <name>DOCKER_MODULETAGVALUE</name>\n          <description>Image generation tag value</description>\n          <defaultValue>latest</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n        <hudson.model.StringParameterDefinition>\n          <name>DOCKER_USERNAMEVALUE</name>\n          <description>Image registry image namespace</description>\n          <defaultValue>onesaitplatform</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n        <hudson.model.StringParameterDefinition>\n          <name>DOCKER_PUSHREGISTRY_PRIVATE</name>\n          <description>Push image to private registry</description>\n          <defaultValue>true</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n        <hudson.model.StringParameterDefinition>\n          <name>PRIVATE_REGISTRY</name>\n          <description>URL to the docker registry</description>\n          <defaultValue>registry.onesaitplatform.com</defaultValue>\n          <trim>false</trim>\n        </hudson.model.StringParameterDefinition>\n      </parameterDefinitions>\n    </hudson.model.ParametersDefinitionProperty>\n    <org.jenkinsci.plugins.workflow.job.properties.PipelineTriggersJobProperty>\n      <triggers/>\n    </org.jenkinsci.plugins.workflow.job.properties.PipelineTriggersJobProperty>\n  </properties>\n  <definition class=\"org.jenkinsci.plugins.workflow.cps.CpsFlowDefinition\" plugin=\"workflow-cps@2.39\">\n    <script>pipeline {\n   // Execute the Pipeline, or stage, on any available agent  \n   agent { \n           node { \n              label &apos;sofia2master&apos; \n            } \n          }\n   \n   tools { \n      maven &apos;maven&apos;\n      jdk &apos;java8&apos;\n   }   \n\n   environment {          \n      // Base sources path \n      BASEPATH = &apos;/datadrive/jenkins/.jenkins/jobs/{{MICROSERVICE_NAME}}/workspace&apos;\n      \n      BASEDIR_PATH = &apos;/datadrive/jenkins/.jenkins/jobs/{{MICROSERVICE_NAME}}/workspace/{{SOURCES_PATH}}/base&apos;\n      BASEPYTHONDIR_PATH = &apos;/datadrive/jenkins/.jenkins/jobs/{{MICROSERVICE_NAME}}/workspace/{{SOURCES_PATH}}/base-python&apos;\n      NOTEBOOKDIR_PATH = &apos;/datadrive/jenkins/.jenkins/jobs/{{MICROSERVICE_NAME}}/workspace/{{SOURCES_PATH}}/notebook&apos;\n\n      SOURCESPATH = &apos;/datadrive/jenkins/.jenkins/jobs/{{MICROSERVICE_NAME}}/workspace/{{SOURCES_PATH}}&apos;\n      //DOCKERPATH = &apos;/datadrive/jenkins/.jenkins/jobs/{{MICROSERVICE_NAME}}/workspace/{{DOCKER_PATH}}&apos;\n      MICROSERVICE_NAME = &apos;{{MICROSERVICE_NAME}}&apos;\n      //CATTLE_ACCESS_KEY = &apos;1CD18DB0F67C50608DC3&apos;\n      //CATTLE_SECRET_KEY = &apos;VXAowSGp27LnNXATGFqqVPwxx9EiPDBSgkjPx8nv&apos;\n   }\n   \n   parameters { \n       string(name: &apos;GIT_URL&apos;, \n              defaultValue: &apos;{{GIT_REPOSITORY}}&apos;, \n              description: &apos;URL Git Repository&apos;)\n       string(name: &apos;GIT_USER&apos;, \n              defaultValue: &apos;{{GIT_USER}}&apos;, \n              description: &apos;URL Git user&apos;)\n       string(name: &apos;GIT_TOKEN&apos;, \n              defaultValue: &apos;{{GIT_TOKEN}}&apos;, \n              description: &apos;Git private tokeny&apos;)\n       string(name: &apos;GIT_BRANCHNAME&apos;, \n              defaultValue: &apos;master&apos;, \n              description: &apos;deploy branch name&apos;)\n       string(name: &apos;DOCKER_MODULETAGVALUE&apos;, \n              defaultValue: &apos;latest&apos;, \n              description: &apos;Image generation tag value&apos;)\n       string(name: &apos;DOCKER_USERNAMEVALUE&apos;, \n              defaultValue: &apos;onesaitplatform&apos;, \n              description: &apos;Image registry image namespace&apos;)\n       string(name: &apos;DOCKER_PUSHREGISTRY_PRIVATE&apos;, \n              defaultValue: &apos;true&apos;, \n              description: &apos;Push image to private registry&apos;)\n       string(name: &apos;PRIVATE_REGISTRY&apos;, \n              defaultValue: &apos;registry.onesaitplatform.com&apos;, \n              description: &apos;URL to the docker registry&apos;)  \n   }    \n   \n   stages {\n       stage(&apos;Fetching from repository&apos;) {  \n        steps {  \n           sh &quot;git clone \\$(echo ${params.GIT_URL} | sed -e \'s/:\\\\/\\\\//:\\\\/\\\\/${params.GIT_USER}:${params.GIT_TOKEN}@/\') ${env.BASEPATH}&quot;           \n        }          \n       }\n     \n     stage(&apos;Build Artifacts&apos;) {\n        steps {\n         // Run maven build\n         dir(&quot;${env.SOURCESPATH}&quot;) {\n         	sh &quot;git checkout ${params.GIT_BRANCHNAME}&quot;\n           }\n        }\n     }\n          \n     stage(&apos;Generate base image&apos;) {  \n        steps { \n            dir(&quot;${env.BASEDIR_PATH}&quot;) { \n                echo &quot;Generating base image&quot;\n                sh &quot;docker build -t zeppelin_alpine .&quot;\n            }\n        }          \n     }\n     \n     stage(&apos;Generate base-python image&apos;) {  \n        steps { \n            dir(&quot;${env.BASEPYTHONDIR_PATH}&quot;) { \n                echo &quot;Generating base-python image&quot;\n                sh &quot;docker build -t zeppelin_alpine_python .&quot;\n            }\n        }          \n     }\n          \n     \n     stage(&apos;Generate Docker notebook image&apos;) {\n   		steps {\n           dir(&quot;${env.NOTEBOOKDIR_PATH}&quot;) {\n                echo &quot;Generating notebook image&quot;\n                sh &quot;docker build -t ${params.DOCKER_USERNAMEVALUE}/{{MICROSERVICE_NAME}}:${DOCKER_MODULETAGVALUE} .&quot;\n                sh &quot;docker image inspect ${params.DOCKER_USERNAMEVALUE}/{{MICROSERVICE_NAME}}:${DOCKER_MODULETAGVALUE}&quot;\n           }\n        }\n     }\n\n     stage(&apos;Push Docker images&apos;) {\n        when {\n          expression { params.DOCKER_PUSHREGISTRY_PRIVATE == &apos;true&apos; }\n        }\n        steps {\n          sh &quot;docker tag ${params.DOCKER_USERNAMEVALUE}/{{MICROSERVICE_NAME}}:${params.DOCKER_MODULETAGVALUE} $PRIVATE_REGISTRY/${params.DOCKER_USERNAMEVALUE}/{{MICROSERVICE_NAME}}:${params.DOCKER_MODULETAGVALUE}&quot;\n          sh &quot;docker push $PRIVATE_REGISTRY/${params.DOCKER_USERNAMEVALUE}/{{MICROSERVICE_NAME}}:${params.DOCKER_MODULETAGVALUE}&quot;\n         \n        }\n     }\n    \n   }\n\n    post {\n        always {\n        	echo &quot;Delete pushed image&quot;\n        	sh &quot;docker rmi -f \\$(docker images | grep \\$DOCKER_USERNAMEVALUE/ | awk &apos;{print \\$3}&apos; | uniq) || true&quot;\n        	\n        	echo &apos;Clean up workspace...&apos;\n        	sh \"rm -r ${env.BASEPATH}\"\n        }   \n	    failure {   \n	    	echo &quot;Delete Untagged images&quot;\n        	sh &quot;docker rmi -f \\$(docker images -f dangling=true -q) || true&quot;\n	    }\n    }\n  \n}</script>\n    <sandbox>true</sandbox>\n  </definition>\n  <triggers/>\n  <disabled>false</disabled>\n</flow-definition>','administrator'),('MASTER-Configuration-21','2026-07-05 18:39:23','Expiration Users config','default','YAML','ExpirationUserPass','EXPIRATIONUSERS','2026-07-05 18:39:23','ExpirationUsersPass: \n   # At 00:00:00am every day\n   cron: \"0 0 0 ? * * *\"\n   # days of life of the pasword with value -1 the restriction is not applied\n   timeLifePass: 180\n   # period of days before the password expires where reminders are sent with value -1 the restriction is not applied\n   noticesDaysBefore: 10\n   #  maximum number of days of inactivity with value -1 the restriction is not applied\n   maxInactiveDays: 30 \nAuthentication:\n   # maximum number of attempts with value -1 restriction is not applied\n   limitFailedAttemp: 5\n   # number of last entries to validate with value -1 the restriction is not applied\n   numberLastEntriesToCheck: 5\nResetUserPass:\n   # hours of validity of the temporary password with value -1 the restriction is not applied\n   hours: 7\n   # At second :00 of minute :00 of every hour\n   cron: \"0 0 * ? * * *\"','administrator'),('MASTER-Configuration-22','2026-07-05 18:39:23','Json dictionary config file for SQL Engine','default','JSON','JsonSqlEngine','SQLENGINE','2026-07-05 18:39:23','{\n  \"concat\": {\n    \"expression\": \"$concat\",\n    \"argsType\": \"array\",\n    \"argsLength\": -1\n  },\n  \"elemAt\": {\n    \"expression\": \"$arrayElemAt\",\n    \"argsType\": \"array\",\n    \"argsLength\": 2\n  },\n  \"toInt\": {\n    \"expression\": \"$toInt\"\n  },\n  \"toBool\": {\n    \"expression\": \"$toBool\"\n  },\n  \"toString\": {\n    \"expression\": \"$toString\"\n  },\n  \"toObjectId\": {\n    \"expression\": \"$toObjectId\"\n  },\n  \"toDouble\": {\n    \"expression\": \"$toDouble\"\n  },\n  \"toLong\": {\n    \"expression\": \"$toLong\"\n  },\n  \"toDate\": {\n    \"expression\": \"$toDate\"\n  },\n  \"toDecimal\": {\n    \"expression\": \"$toDecimal\"\n  },\n  \"lower\": {\n    \"expression\": \"$toLower\"\n  },\n  \"upper\": {\n    \"expression\": \"$toUpper\"\n  },\n  \"substring\": {\n    \"expression\": \"$substr\",\n    \"argsType\": \"array\",\n    \"argsLength\": 3,\n    \"comment\": \"{ $substr: [ <string>, <start>, <length> ]\"\n  },\n  \"length\": {\n    \"expression\": \"$strLenCP\"\n  },\n  \"date_part\": {\n    \"type\": \"switchbyargument\",\n    \"switchbyargument\":{\n      \"argument\": 0,\n      \"switch\": {\n        \"month\": \"$month\",\n        \"year\": \"$year\",\n        \"day\": \"$dayOfMonth\",\n        \"dayOfMonth\": \"$dayOfMonth\",\n        \"hour\": \"$hour\",\n        \"minute\": \"$minute\",\n        \"second\": \"$second\",\n        \"millisecond\": \"$millisecond\",\n        \"dayOfYear\": \"$dayOfYear\",\n        \"dayOfWeek\": \"$dayOfWeek\",\n        \"week\": \"$week\"\n      }\n    },\n    \"argsType\": \"direct\",\n    \"argsLength\": 2,\n    \"comment\": \"date_part(\\\"year\\\",c.dateLastUpdate)\"\n  },\n  \"to_timestamp\": {\n    \"type\": \"CUSTOMEXP\",\n    \"expression\": {\n      \"$dateFromString\": {\n        \"dateString\":\"${0}|allowNested\"\n      }\n    }\n  },\n  \"timestamp\": {\n    \"type\": \"CUSTOMEXP\",\n    \"expression\": {\n      \"$dateFromString\": {\n        \"dateString\":\"${0}|allowNested\"\n      }\n    }\n  },\n  \"trim\": {\n    \"type\": \"customexp\",\n    \"expression\": {\n      \"$trim\": {\n        \"input\":\"${0}|allowNested\"\n      }\n    }\n  },\n  \"geoWithin\": {\n    \"steps\": [\"where\"],\n    \"type\": \"customexp\",\n    \"expression\": {\n      \"${0}|nodollar\": {\n        \"$geoWithin\": {\n          \"$geometry\": \"${1}|jsonParse\"\n        }\n      }\n    },\n    \"argsType\": \"direct\",\n    \"argsLength\": 2,\n    \"comment\": \"geowithin(field, geometry)\"\n  },\n  \"unzip\": {\n    \"steps\": [\"project\"],\n    \"type\": \"customexp\",\n    \"preExpressionSteps\": [{\n      \"$unwind\": {\n        \"path\": \"${0}\",\n        \"preserveNullAndEmptyArrays\": \"${1}\"\n      }\n    }],\n    \"argsLength\": 2,\n    \"unique\": true\n  },\n  \"unzipts\": {\n    \"steps\": [\"project\"],\n    \"type\": \"customcode\",\n    \"preCodeFn\": \"tsPreSteps\",\n    \"codeFn\": \"tsExp\",\n    \"argsLength\": 2,\n    \"unique\": true\n  },\n  \"ifNull\": {\n    \"expression\": \"$ifNull\",\n    \"argsType\": \"array\",\n    \"argsLength\": 2\n  },\n  \"pow\": {\n    \"expression\": \"$pow\",\n    \"argsType\": \"array\",\n    \"argsLength\": 2\n  },\n  \"mod\": {\n    \"expression\": \"$mod\",\n    \"argsType\": \"array\",\n    \"argsLength\": 2\n  },\n  \"floor\": {\n    \"expression\": \"$floor\"\n  },\n  \"ceil\": {\n    \"expression\": \"$ceil\"\n  },\n  \"dateFromParts\": {\n    \"type\": \"customexp\",\n    \"expression\": {\n      \"$dateFromParts\": {\n        \"year\":\"${0}|allowNested\",\n        \"month\":\"${1}|allowNested\",\n        \"day\":\"${2}|allowNested\"\n      }\n    },\n    \"argsLength\": 3\n  },\n  \"round\": {\n    \"expression\": \"$round\",\n    \"argsType\": \"array\",\n    \"argsLength\": 2\n  }\n}\n','administrator'),('MASTER-Configuration-23','2026-07-05 18:39:23','Java class util file for SQL Engine','default',NULL,'JavaSqlEngine','SQLENGINE','2026-07-05 18:39:23','/*\n * Copyright Indra Soluciones TecnologÃ­as de la InformaciÃ³n, S.L.U.\n * 2013-2024 SPAIN\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *      http://www.apache.org/licenses/LICENSE-2.0\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\nimport com.github.vincentrussell.query.mongodb.sql.converter.holder.MongoDBQueryHolder;\nimport net.sf.jsqlparser.expression.Expression;\nimport net.sf.jsqlparser.expression.StringValue;\nimport org.bson.Document;\n\nimport java.util.LinkedList;\nimport java.util.List;\n\npublic final class UtilsCode {\n    public enum WINDOWTS {\n        SECONDS,\n        MINUTES,\n        HOURS,\n        DAYS,\n        MONTHS\n    }\n\n    private static final int[] TIMETOSEG =  new int[] {1, 60, 3600, 86400};\n\n    private static final int[] TIMETONEXT =  new int[] {1, 60, 60, 24};\n\n    /**\n     * previous steps for timeseries unzip by n levels.\n     * This use the period and frecuency for calculating this variable steps\n     * @param le params: 0 upper(period), 1 lower(frecuency)\n     * @param mongoDBQueryHolder\n     * @return list of documents for previous steps in unzip ts\n     */\n    public static List<Document> tsPreSteps(final List<Expression> le, final MongoDBQueryHolder mongoDBQueryHolder) {\n        WINDOWTS windowh = WINDOWTS.valueOf(((StringValue) le.get(0)).getValue().toUpperCase());\n        WINDOWTS windowl = WINDOWTS.valueOf(((StringValue) le.get(1)).getValue().toUpperCase());\n\n        List<Document> ldocs = new LinkedList<>();\n        ldocs.add(\n                Document.parse(\"{\\n\"\n                        + \"            \\\"$project\\\": {\\n\"\n                        + \"                \\\"TimeSerie\\\": 1,\\n\"\n                        + \"                \\\"tmpArray\\\": { \\\"$objectToArray\\\": \\\"$TimeSerie.values.v\\\" }\\n\"\n                        + \"                \\\"tmpIndex\\\": { \\\"$literal\\\": 0 }\\n\"\n                        + \"            },\\n\"\n                        + \"        }\")\n        );\n\n        ldocs.add(\n                Document.parse(\"{\\n\"\n                        + \"            \\\"$unwind\\\": \\\"$tmpArray\\\"\\n\"\n                        + \"        }\")\n        );\n\n        for (int i = windowh.ordinal() - 1; i > windowl.ordinal(); i--) {\n            ldocs.add(\n                    Document.parse(\"{\\n\"\n                            + \"            \\\"$project\\\": {\\n\"\n                            + \"                \\\"TimeSerie\\\": 1,\\n\"\n                            + \"                \\\"tmpIndex\\\": { \"\n                            + \"                     \\\"$multiply\\\": [\"\n                            +                            \"{\\\"$sum\\\":[\\\"$tmpIndex\\\",{\\\"$toInt\\\":\\\"$tmpArray.k\\\"}]},\"\n                            +                            TIMETONEXT[i]\n                            + \"                     ]},\\n\"\n                            + \"                \\\"tmpArray\\\": { \\\"$objectToArray\\\": \\\"$tmpArray.v\\\" }\\n\"\n                            + \"            }\\n\"\n                            + \"        }\")\n            );\n            ldocs.add(\n                    Document.parse(\"{\\n\"\n                            + \"            \\\"$unwind\\\": \\\"$tmpArray\\\"\\n\"\n                            + \"        }\")\n            );\n        }\n\n        ldocs.add(\n                Document.parse(\"{\\n\"\n                        + \"            \\\"$addFields\\\": {\\n\"\n                        + \"                \\\"TimeSerie.value\\\": \\\"$tmpArray.v\\\",\\n\"\n                        + \"                \\\"TimeSerie.timestamp\\\": {\\n\"\n                        + \"                    \\\"$dateFromParts\\\": {\\n\"\n                        + \"                        \\\"year\\\": { \\\"$year\\\": \\\"$TimeSerie.timestamp\\\" },\\n\"\n                        + \"                        \\\"month\\\": { \\\"$month\\\": \\\"$TimeSerie.timestamp\\\" },\\n\"\n                        + \"                        \\\"day\\\": { \\\"$dayOfMonth\\\": \\\"$TimeSerie.timestamp\\\" },\\n\"\n                        + \"                        \\\"hour\\\": { \\\"$hour\\\": \\\"$TimeSerie.timestamp\\\" },\\n\"\n                        + \"                        \\\"minute\\\": { \\\"$minute\\\": \\\"$TimeSerie.timestamp\\\" },\\n\"\n                        + \"                        \\\"second\\\": { \\\"$multiply\\\": [\"\n                        + \"                                 {\\\"$sum\\\":[\\\"$tmpIndex\\\",{\\\"$toInt\\\":\\\"$tmpArray.k\\\"}]},\"\n                        +                                   TIMETOSEG[windowl.ordinal()] + \"]}\\n\"\n                        + \"                    }\\n\"\n                        + \"                }\\n\"\n                        + \"            }\\n\"\n                        + \"        }\")\n        );\n\n        return ldocs;\n    }\n\n    /**\n     * include ts fields in project, combine then with previous.\n     * @param le\n     * @param mongoDBQueryHolder\n     * @return null\n     */\n    public static Document tsExp(final List<Expression> le, final MongoDBQueryHolder mongoDBQueryHolder) {\n        mongoDBQueryHolder.getProjection().put(\"tmpArray\", 0);\n        mongoDBQueryHolder.getProjection().put(\"tmpIndex\", 0);\n        mongoDBQueryHolder.getProjection().put(\"TimeSerie.values\", 0);\n        return null;\n    }\n}','administrator'),('MASTER-Configuration-24','2026-07-05 18:39:22','Lineage Config','default','JSON','Lineage','LINEAGE','2026-07-05 18:39:22','[{\n		\"id\": \"com_streamsets_pipeline_stage_origin_spooldir_SpoolDirDSource\",\n		\"defaultLanguage\": \"en\",\n		\"icon\": \"pipe\",\n		\"en\": {\n			\"label\": \"Directory\",\n			\"properties\": {\n				\"conf.spoolDir\": \"Files Directory\",\n				\"conf.filePattern\": \"File Pattern\"\n			}\n		},\n		\"es\": {\n			\"label\": \"Directorio\",\n			\"properties\": {\n				\"conf.spoolDir\": \"Directorio\",\n				\"conf.filePattern\": \"Archivo\"\n			}\n		}\n	}\n]\n','administrator'),('MASTER-Configuration-25','2026-07-05 18:39:22','Administrator Panel Configuration','default','YAML','ADMIN_PANEL','CUSTOM','2026-07-05 18:39:22','modules:\n   engine:\n      -  \n         name: Api Manager \n         namespace: onesait-platform\n         pod: apimanagerservice\n      -  \n         name: Flow Engine \n         namespace: onesait-platform\n         pod: flowengineservice\n      -  \n         name: Rules Engine \n         namespace: onesait-platform\n         pod: rules-engine-service\n      -  \n         name: Identity Manager \n         namespace: onesait-platform\n         pod: oauthservice\n      -  \n         name: Elastic DB \n         namespace: onesait-platform\n         pod: elasticdb\n      -  \n         name: Realtime DB\n         namespace: onesait-platform\n         pod: realtimedb\n      -  \n         name: Semantic Broker \n         namespace: onesait-platform\n         pod: routerservice	\n      -  \n         name: BPM Engine \n         namespace: onesait-platform\n         pod: bpmengine	\n      -  \n         name: Control Panel\n         namespace: onesait-platform\n         pod: controlpanelservice\n      -  \n         name: Log Centralizer\n         namespace: onesait-platform\n         pod: log-centralizer\n      -  \n         name: Kafka\n         namespace: onesait-platform\n         pod: kafkaservice\n      -   \n         name: Monitoring UI\n         namespace: onesait-platform\n         pod: monitoringuiservice\n      -  \n         name: Digital Broker \n         namespace: onesait-platform\n         pod: iotbrokerservice\n      -  \n         name: Gravitee Gateway\n         namespace: onesait-platform\n         pod: graviteegatewayservice\n   intelligence:\n      -  \n         name: Dataflow \n         namespace: onesait-platform\n         pod: streamsets\n      -  \n         name: Notebooks \n         namespace: onesait-platform\n         pod: zeppelin\n      -  \n         name: Data Refiner \n         namespace: onesait-platform\n         pod: datacleanerservice\n      -  \n         name: Dashboard Engine \n         namespace: onesait-platform\n         pod: dashboardengineservice	\n      -  \n         name: Report Engine \n         namespace: onesait-platform\n         pod: reportengine	\n      -  \n         name: Open Data Portal \n         namespace: onesait-platform\n         pod: ckanservice\n   things:\n      -  \n         name: Digital Twin Broker \n         namespace: onesait-platform\n         pod: digitaltwinbrokerservice','administrator'),('MASTER-Configuration-27','2026-07-05 18:39:22','BillableModules for local environment','default','JSON','BillableModules','ENDPOINT_MODULES','2026-07-05 18:39:22','[{\n    \"module\": \"controlpanel\",\n    \"name\": \"Controlpanel\",\n    \"servicename\": \"localhost\",\n    \"port\": 18000\n}, {\n    \"module\": \"iotbroker\",\n    \"name\": \"IoTBroker\",\n    \"servicename\": \"localhost\",\n    \"port\": 19000\n}, {\n    \"module\": \"identitymanager\",\n    \"name\": \"Identity Manager\",\n    \"servicename\": \"localhost\",\n    \"port\": 21000\n}, {\n    \"module\": \"keycloak\",\n    \"name\": \"Advanced Identity Manager (Keycloak)\",\n    \"servicename\": \"localhost\",\n    \"port\": 15500\n}, {\n    \"module\": \"logcentralizado\",\n    \"name\": \"Centraliced Log\",\n    \"servicename\": \"localhost\",\n    \"port\": 12201\n}, {\n    \"module\": \"flowengine\",\n    \"name\": \"Flow Engine\",\n    \"servicename\": \"localhost\",\n    \"port\": 20100\n}, {\n    \"module\": \"apimanager\",\n    \"name\": \"API Manager\",\n    \"servicename\": \"localhost\",\n    \"port\": 19100\n},{\n    \"module\": \"gravitee\",\n    \"name\": \"Advanced API Manager (Gravitee)\",\n    \"servicename\": \"localhost\",\n    \"port\": 25000\n}, {\n    \"module\": \"ruleengine\",\n    \"name\": \"Rules Engine\",\n    \"servicename\": \"localhost\",\n    \"port\": 20200\n}, {\n    \"module\": \"bpmengine\",\n    \"name\": \"BPM Engine\",\n    \"servicename\": \"localhost\",\n    \"port\": 27000\n}, {\n    \"module\": \"digitaltwinbroker\",\n    \"name\": \"Digital Twin Broker\",\n    \"servicename\": \"localhost\",\n    \"port\": 19300\n}, {\n    \"module\": \"kafka\",\n    \"name\": \"Kafka\",\n    \"servicename\": \"localhost\",\n    \"port\": 18400\n}, {\n    \"module\": \"dashboardengine\",\n    \"name\": \"Dashboard Engine\",\n    \"servicename\": \"localhost\",\n    \"port\": 18300\n}, {\n    \"module\": \"dataflow\",\n    \"name\": \"Dataflow\",\n    \"servicename\": \"localhost\",\n    \"port\": 18630\n}, {\n    \"module\": \"notebooks\",\n    \"name\": \"Notebooks\",\n    \"servicename\": \"localhost\",\n    \"port\": 8080\n}, {\n    \"module\": \"datacleaner\",\n    \"name\": \"Data Refiner\",\n    \"servicename\": \"localhost\",\n    \"port\": 3333\n}, {\n    \"module\": \"portalopendata\",\n    \"name\": \"Open Data (CKAN)\",\n    \"servicename\": \"localhost\",\n    \"port\": 5000\n}, {\n    \"module\": \"realtimedb\",\n    \"name\": \"RealtimeDB (MongoDB)\",\n    \"servicename\": \"localhost\",\n    \"port\": 27017\n}, {\n    \"module\": \"historicaldb\",\n    \"name\": \"HistoricalDB \",\n    \"servicename\": \"localhost\",\n    \"port\": 9000\n},{\n    \"module\": \"presto\",\n    \"name\": \"PrestoDB\",\n    \"servicename\": \"localhost\",\n    \"port\": 8080\n},\n{\n    \"module\": \"nebulagraph\",\n    \"name\": \"Nebula Graph DB\",\n    \"servicename\": \"localhost\",\n    \"port\": 9669\n},\n{\n    \"module\": \"datalabeling\",\n    \"name\": \"Data labeling\",\n    \"servicename\": \"localhost\",\n    \"port\": 8080\n}\n]\n','administrator'),('MASTER-Configuration-28','2026-07-05 18:39:22','BillableModules for docker environment','docker','JSON','BillableModules','ENDPOINT_MODULES','2026-07-05 18:39:22','[{\n    \"module\": \"controlpanel\",\n    \"name\": \"Controlpanel\",\n    \"servicename\": \"controlpanelservice\",\n    \"port\": 18000\n}, {\n    \"module\": \"iotbroker\",\n    \"name\": \"IoTBroker\",\n    \"servicename\": \"iotbrokerservice\",\n    \"port\": 19000\n}, {\n    \"module\": \"identitymanager\",\n    \"name\": \"Identity Manager\",\n    \"servicename\": \"oauthservice\",\n    \"port\": 21000\n}, {\n    \"module\": \"keycloak\",\n    \"name\": \"Advanced Identity Manager (Keycloak)\",\n    \"servicename\": \"keycloakmanager\",\n    \"port\": 15500\n}, {\n    \"module\": \"logcentralizado\",\n    \"name\": \"Centraliced Log\",\n    \"servicename\": \"log-centralizer\",\n    \"port\": 12201\n}, {\n    \"module\": \"flowengine\",\n    \"name\": \"Flow Engine\",\n    \"servicename\": \"flowengineservice\",\n    \"port\": 20100\n}, {\n    \"module\": \"apimanager\",\n    \"name\": \"API Manager\",\n    \"servicename\": \"apimanagerservice\",\n    \"port\": 19100\n},{\n    \"module\": \"gravitee\",\n    \"name\": \"Advanced API Manager (Gravitee)\",\n    \"servicename\": \"graviteemngservice\",\n    \"port\": 8083\n}, {\n    \"module\": \"ruleengine\",\n    \"name\": \"Rules Engine\",\n    \"servicename\": \"rules-engine-service\",\n    \"port\": 20200\n}, {\n    \"module\": \"bpmengine\",\n    \"name\": \"BPM Engine\",\n    \"servicename\": \"bpmengine\",\n    \"port\": 27000\n}, {\n    \"module\": \"digitaltwinbroker\",\n    \"name\": \"Digital Twin Broker\",\n    \"servicename\": \"digitaltwinbrokerservice\",\n    \"port\": 19300\n}, {\n    \"module\": \"kafka\",\n    \"name\": \"Kafka\",\n    \"servicename\": \"kafkamonitoringservice\",\n    \"port\": 18400\n}, {\n    \"module\": \"dashboardengine\",\n    \"name\": \"Dashboard Engine\",\n    \"servicename\": \"dashboardengineservice\",\n    \"port\": 18300\n}, {\n    \"module\": \"dataflow\",\n    \"name\": \"Dataflow\",\n    \"servicename\": \"streamsets\",\n    \"port\": 18630\n}, {\n    \"module\": \"notebooks\",\n    \"name\": \"Notebooks\",\n    \"servicename\": \"zeppelin\",\n    \"port\": 8080\n}, {\n    \"module\": \"datacleaner\",\n    \"name\": \"Data Refiner\",\n    \"servicename\": \"datacleanerservice\",\n    \"port\": 3333\n}, {\n    \"module\": \"portalopendata\",\n    \"name\": \"Open Data (CKAN)\",\n    \"servicename\": \"ckanservice\",\n    \"stack\": \"opendata\",\n    \"port\": 5000\n}, {\n    \"module\": \"realtimedb\",\n    \"name\": \"RealtimeDB (MongoDB)\",\n    \"servicename\": \"realtimedb\",\n    \"port\": 27017\n}, {\n    \"module\": \"historicaldb\",\n    \"name\": \"HistoricalDB \",\n    \"servicename\": \"minio\",\n    \"port\": 9000\n},{\n    \"module\": \"presto\",\n    \"name\": \"PrestoDB\",\n    \"servicename\": \"presto-coordinator\",\n    \"port\": 8080\n},\n{\n    \"module\": \"nebulagraph\",\n    \"name\": \"Nebula Graph DB\",\n    \"servicename\": \"graphd.nebula\",\n    \"port\": 9669\n},\n{\n    \"module\": \"datalabeling\",\n    \"name\": \"Data labeling\",\n    \"servicename\": \"datalabelingservice\",\n    \"port\": 8080\n}\n]\n','administrator'),('MASTER-Configuration-29','2026-07-05 18:39:23','Kafka connection and topic properties for clients.','default','JSON','Kafka Client Properties','KAFKA_PROPERTIES','2026-07-05 18:39:23','{\n	\"AdminClient\":[\n	  {\n	    \"id\": \"ssl.key.password\",\n	    \"description\": \"The password of the private key in the key store file orthe PEM key specified in `ssl.keystore.key\'. This is required for clients only if two-way authentication is configured.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.keystore.certificate.chain\",\n	    \"description\": \"Certificate chain in the format specified by \'ssl.keystore.type\'. Default SSL engine factory supports only PEM format with a list of X.509 certificates\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.keystore.key\",\n	    \"description\": \"Private key in the format specified by \'ssl.keystore.type\'. Default SSL engine factory supports only PEM format with PKCS#8 keys. If the key is encrypted, key password must be specified using \'ssl.key.password\'\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.keystore.location\",\n	    \"description\": \"The location of the key store file. This is optional for client and can be used for two-way authentication for client.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.keystore.password\",\n	    \"description\": \"The store password for the key store file. This is optional for client and only needed if \'ssl.keystore.location\' is configured. Key store password is not supported for PEM format.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.truststore.certificates\",\n	    \"description\": \"Trusted certificates in the format specified by \'ssl.truststore.type\'. Default SSL engine factory supports only PEM format with X.509 certificates.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.truststore.location\",\n	    \"description\": \"The location of the trust store file.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.truststore.password\",\n	    \"description\": \"The password for the trust store file. If a password is not set, trust store file configured will still be used, but integrity checking is disabled. Trust store password is not supported for PEM format.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"client.dns.lookup\",\n	    \"description\": \"Controls how the client uses DNS lookups. If set to use_all_dns_ips, connect to each returned IP address in sequence until a successful connection is established. After a disconnection, the next IP is used. Once all IPs have been used once, the client resolves the IP(s) from the hostname again (both the JVM and the OS cache DNS name lookups, however). If set to resolve_canonical_bootstrap_servers_only, resolve each bootstrap address into a list of canonical names. After the bootstrap phase, this behaves the same as use_all_dns_ips.\",\n	    \"defaultValue\": \"use_all_dns_ips\"\n	  },\n	  {\n	    \"id\": \"client.id\",\n	    \"description\": \"An id string to pass to the server when making requests. The purpose of this is to be able to track the source of requests beyond just ip/port by allowing a logical application name to be included in server-side request logging.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"connections.max.idle.ms\",\n	    \"description\": \"Close idle connections after the number of milliseconds specified by this config.\",\n	    \"defaultValue\": \"300000\"\n	  },\n	  {\n	    \"id\": \"default.api.timeout.ms\",\n	    \"description\": \"Specifies the timeout (in milliseconds) for client APIs. This configuration is used as the default timeout for all client operations that do not specify a timeout parameter.\",\n	    \"defaultValue\": \"60000\"\n	  },\n	  {\n	    \"id\": \"receive.buffer.bytes\",\n	    \"description\": \"The size of the TCP receive buffer (SO_RCVBUF) to use when reading data. If the value is -1, the OS default will be used.\",\n	    \"defaultValue\": \"65536\"\n	  },\n	  {\n	    \"id\": \"request.timeout.ms\",\n	    \"description\": \"The configuration controls the maximum amount of time the client will wait for the response of a request. If the response is not received before the timeout elapses the client will resend the request if necessary or fail the request if retries are exhausted.\",\n	    \"defaultValue\": \"30000\"\n	  },\n	  {\n	    \"id\": \"sasl.client.callback.handler.class\",\n	    \"description\": \"The fully qualified name of a SASL client callback handler class that implements the AuthenticateCallbackHandler interface.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"sasl.jaas.config\",\n	    \"description\": \"JAAS login context parameters for SASL connections in the format used by JAAS configuration files. JAAS configuration file format is described here. The format for the value is: loginModuleClass controlFlag (optionName=optionValue)*;. For brokers, the config must be prefixed with listener prefix and SASL mechanism name in lower-case. For example, listener.name.sasl_ssl.scram-sha-256.sasl.jaas.config=com.example.ScramLoginModule required;\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"sasl.kerberos.service.name\",\n	    \"description\": \"The Kerberos principal name that Kafka runs as. This can be defined either in Kafka\'s JAAS config or in Kafka\'s config.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"sasl.login.callback.handler.class\",\n	    \"description\": \"The fully qualified name of a SASL login callback handler class that implements the AuthenticateCallbackHandler interface. For brokers, login callback handler config must be prefixed with listener prefix and SASL mechanism name in lower-case. For example, listener.name.sasl_ssl.scram-sha-256.sasl.login.callback.handler.class=com.example.CustomScramLoginCallbackHandler\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"sasl.login.class\",\n	    \"description\": \"The fully qualified name of a class that implements the Login interface. For brokers, login config must be prefixed with listener prefix and SASL mechanism name in lower-case. For example, listener.name.sasl_ssl.scram-sha-256.sasl.login.class=com.example.CustomScramLogin\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"sasl.mechanism\",\n	    \"description\": \"SASL mechanism used for client connections. This may be any mechanism for which a security provider is available. GSSAPI is the default mechanism.\",\n	    \"defaultValue\": \"GSSAPI\"\n	  },\n	  {\n	    \"id\": \"security.protocol\",\n	    \"description\": \"Protocol used to communicate with brokers. \",\n	    \"defaultValue\": \"PLAINTEXT\"\n	  },\n	  {\n	    \"id\": \"send.buffer.bytes\",\n	    \"description\": \"The size of the TCP send buffer (SO_SNDBUF) to use when sending data. If the value is -1, the OS default will be used.\",\n	    \"defaultValue\": \"131072\"\n	  },\n	  {\n	    \"id\": \"socket.connection.setup.timeout.max.ms\",\n	    \"description\": \"The maximum amount of time the client will wait for the socket connection to be established. The connection setup timeout will increase exponentially for each consecutive connection failure up to this maximum. To avoid connection storms, a randomization factor of 0.2 will be applied to the timeout resulting in a random range between 20% below and 20% above the computed value.\",\n	    \"defaultValue\": \"30000\"\n	  },\n	  {\n	    \"id\": \"socket.connection.setup.timeout.ms\",\n	    \"description\": \"The amount of time the client will wait for the socket connection to be established. If the connection is not built before the timeout elapses, clients will close the socket channel.\",\n	    \"defaultValue\": \"10000\"\n	  },\n	  {\n	    \"id\": \"ssl.enabled.protocols\",\n	    \"description\": \"The list of protocols enabled for SSL connections. The default is \'TLSv1.2,TLSv1.3\' when running with Java 11 or newer, \'TLSv1.2\' otherwise. With the default value for Java 11, clients and servers will prefer TLSv1.3 if both support it and fallback to TLSv1.2 otherwise (assuming both support at least TLSv1.2). This default should be fine for most cases. Also see the config documentation for `ssl.protocol`.\",\n	    \"defaultValue\": \"TLSv1.2\"\n	  },\n	  {\n	    \"id\": \"ssl.keystore.type\",\n	    \"description\": \"The file format of the key store file. This is optional for client.\",\n	    \"defaultValue\": \"JKS\"\n	  },\n	  {\n	    \"id\": \"ssl.protocol\",\n	    \"description\": \"The SSL protocol used to generate the SSLContext. The default is \'TLSv1.3\' when running with Java 11 or newer, \'TLSv1.2\' otherwise. This value should be fine for most use cases. Allowed values in recent JVMs are \'TLSv1.2\' and \'TLSv1.3\'. \'TLS\', \'TLSv1.1\', \'SSL\', \'SSLv2\' and \'SSLv3\' may be supported in older JVMs, but their usage is discouraged due to known security vulnerabilities. With the default value for this config and \'ssl.enabled.protocols\', clients will downgrade to \'TLSv1.2\' if the server does not support \'TLSv1.3\'. If this config is set to \'TLSv1.2\', clients will not use \'TLSv1.3\' even if it is one of the values in ssl.enabled.protocols and the server only supports \'TLSv1.3\'.\",\n	    \"defaultValue\": \"TLSv1.2\"\n	  },\n	  {\n	    \"id\": \"ssl.provider\",\n	    \"description\": \"The name of the security provider used for SSL connections. Default value is the default security provider of the JVM.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.truststore.type\",\n	    \"description\": \"The file format of the trust store file.\",\n	    \"defaultValue\": \"JKS\"\n	  },\n	  {\n	    \"id\": \"host.resolver.class\",\n	    \"description\": \"Class to use for resolving a host name\",\n	    \"defaultValue\": \"org.apache.kafka.clients.DefaultHostResolver\"\n	  },\n	  {\n	    \"id\": \"metadata.max.age.ms\",\n	    \"description\": \"The period of time in milliseconds after which we force a refresh of metadata even if we haven\'t seen any partition leadership changes to proactively discover any new brokers or partitions.\",\n	    \"defaultValue\": \"300000\"\n	  },\n	  {\n	    \"id\": \"metric.reporters\",\n	    \"description\": \"A list of classes to use as metrics reporters. Implementing the org.apache.kafka.common.metrics.MetricsReporter interface allows plugging in classes that will be notified of new metric creation. The JmxReporter is always included to register JMX statistics.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"metrics.num.samples\",\n	    \"description\": \"The number of samples maintained to compute metrics.\",\n	    \"defaultValue\": \"2\"\n	  },\n	  {\n	    \"id\": \"metrics.recording.level\",\n	    \"description\": \"The highest recording level for metrics.\",\n	    \"defaultValue\": \"INFO\"\n	  },\n	  {\n	    \"id\": \"metrics.sample.window.ms\",\n	    \"description\": \"The window of time a metrics sample is computed over.\",\n	    \"defaultValue\": \"30000\"\n	  },\n	  {\n	    \"id\": \"reconnect.backoff.max.ms\",\n	    \"description\": \"The maximum amount of time in milliseconds to wait when reconnecting to a broker that has repeatedly failed to connect. If provided, the backoff per host will increase exponentially for each consecutive connection failure, up to this maximum. After calculating the backoff increase, 20% random jitter is added to avoid connection storms.\",\n	    \"defaultValue\": \"1000\"\n	  },\n	  {\n	    \"id\": \"reconnect.backoff.ms\",\n	    \"description\": \"The base amount of time to wait before attempting to reconnect to a given host. This avoids repeatedly connecting to a host in a tight loop. This backoff applies to all connection attempts by the client to a broker.\",\n	    \"defaultValue\": \"50\"\n	  },\n	  {\n	    \"id\": \"retries\",\n	    \"description\": \"Setting a value greater than zero will cause the client to resend any request that fails with a potentially transient error. It is recommended to set the value to either zero or `MAX_VALUE` and use corresponding timeout parameters to control how long a client should retry a request.\",\n	    \"defaultValue\": \"2147483647\"\n	  },\n	  {\n	    \"id\": \"retry.backoff.ms\",\n	    \"description\": \"The amount of time to wait before attempting to retry a failed request. This avoids repeatedly sending requests in a tight loop under some failure scenarios.\",\n	    \"defaultValue\": \"100\"\n	  },\n	  {\n	    \"id\": \"sasl.kerberos.kinit.cmd\",\n	    \"description\": \"Kerberos kinit command path.\",\n	    \"defaultValue\": \"/usr/bin/kinit\"\n	  },\n	  {\n	    \"id\": \"sasl.kerberos.min.time.before.relogin\",\n	    \"description\": \"Login thread sleep time between refresh attempts.\",\n	    \"defaultValue\": \"60000\"\n	  },\n	  {\n	    \"id\": \"sasl.kerberos.ticket.renew.jitter\",\n	    \"description\": \"Percentage of random jitter added to the renewal time.\",\n	    \"defaultValue\": \"0.05\"\n	  },\n	  {\n	    \"id\": \"sasl.kerberos.ticket.renew.window.factor\",\n	    \"description\": \"Login thread will sleep until the specified window factor of time from last refresh to ticket\'s expiry has been reached, at which time it will try to renew the ticket.\",\n	    \"defaultValue\": \"0.8\"\n	  },\n	  {\n	    \"id\": \"sasl.login.refresh.buffer.seconds\",\n	    \"description\": \"The amount of buffer time before credential expiration to maintain when refreshing a credential, in seconds. If a refresh would otherwise occur closer to expiration than the number of buffer seconds then the refresh will be moved up to maintain as much of the buffer time as possible. Legal values are between 0 and 3600 (1 hour); a default value of 300 (5 minutes) is used if no value is specified. This value and sasl.login.refresh.min.period.seconds are both ignored if their sum exceeds the remaining lifetime of a credential. Currently applies only to OAUTHBEARER.\",\n	    \"defaultValue\": \"300\"\n	  },\n	  {\n	    \"id\": \"sasl.login.refresh.min.period.seconds\",\n	    \"description\": \"The desired minimum time for the login refresh thread to wait before refreshing a credential, in seconds. Legal values are between 0 and 900 (15 minutes); a default value of 60 (1 minute) is used if no value is specified. This value and sasl.login.refresh.buffer.seconds are both ignored if their sum exceeds the remaining lifetime of a credential. Currently applies only to OAUTHBEARER.\",\n	    \"defaultValue\": \"60\"\n	  },\n	  {\n	    \"id\": \"sasl.login.refresh.window.factor\",\n	    \"description\": \"Login refresh thread will sleep until the specified window factor relative to the credential\'s lifetime has been reached, at which time it will try to refresh the credential. Legal values are between 0.5 (50%) and 1.0 (100%) inclusive; a default value of 0.8 (80%) is used if no value is specified. Currently applies only to OAUTHBEARER.\",\n	    \"defaultValue\": \"0.8\"\n	  },\n	  {\n	    \"id\": \"sasl.login.refresh.window.jitter\",\n	    \"description\": \"The maximum amount of random jitter relative to the credential\'s lifetime that is added to the login refresh thread\'s sleep time. Legal values are between 0 and 0.25 (25%) inclusive; a default value of 0.05 (5%) is used if no value is specified. Currently applies only to OAUTHBEARER.\",\n	    \"defaultValue\": \"0.05\"\n	  },\n	  {\n	    \"id\": \"security.providers\",\n	    \"description\": \"A list of configurable creator classes each returning a provider implementing security algorithms. These classes should implement the org.apache.kafka.common.security.auth.SecurityProviderCreator interface.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.cipher.suites\",\n	    \"description\": \"A list of cipher suites. This is a named combination of authentication, encryption, MAC and key exchange algorithm used to negotiate the security settings for a network connection using TLS or SSL network protocol. By default all the available cipher suites are supported.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.endpoint.identification.algorithm\",\n	    \"description\": \"The endpoint identification algorithm to validate server hostname using server certificate.\",\n	    \"defaultValue\": \"https\"\n	  },\n	  {\n	    \"id\": \"ssl.engine.factory.class\",\n	    \"description\": \"The class of type org.apache.kafka.common.security.auth.SslEngineFactory to provide SSLEngine objects. Default value is org.apache.kafka.common.security.ssl.DefaultSslEngineFactory\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.keymanager.algorithm\",\n	    \"description\": \"The algorithm used by key manager factory for SSL connections. Default value is the key manager factory algorithm configured for the Java Virtual Machine.\",\n	    \"defaultValue\": \"SunX509\"\n	  },\n	  {\n	    \"id\": \"ssl.secure.random.implementation\",\n	    \"description\": \"The SecureRandom PRNG implementation to use for SSL cryptography operations.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"ssl.trustmanager.algorithm\",\n	    \"description\": \"The algorithm used by trust manager factory for SSL connections. Default value is the trust manager factory algorithm configured for the Java Virtual Machine.\",\n	    \"defaultValue\": \"PKIX\"\n	  }\n	],\n	\"topics\":[\n	  {\n	    \"id\": \"cleanup.policy\",\n	    \"description\": \"A string that is either \'delete\' or \'compact\' or both. This string designates the retention policy to use on old log segments. The default policy (\'delete\') will discard old segments when their retention time or size limit has been reached. The \'compact\' setting will enable log compaction on the topic.\",\n	    \"defaultValue\": \"delete\"\n	  },\n	  {\n	    \"id\": \"compression.type\",\n	    \"description\": \"Specify the final compression type for a given topic. This configuration accepts the standard compression codecs (\'gzip\', \'snappy\', \'lz4\', \'zstd\'). It additionally accepts \'uncompressed\' which is equivalent to no compression; and \'producer\' which means retain the original compression codec set by the producer.\",\n	    \"defaultValue\": \"producer\"\n	  },\n	  {\n	    \"id\": \"delete.retention.ms\",\n	    \"description\": \"The amount of time to retain delete tombstone markers for log compacted topics. This setting also gives a bound on the time in which a consumer must complete a read if they begin from offset 0 to ensure that they get a valid snapshot of the final stage (otherwise delete tombstones may be collected before they complete their scan).\",\n	    \"defaultValue\": \"86400000\"\n	  },\n	  {\n	    \"id\": \"file.delete.delay.ms\",\n	    \"description\": \"The time to wait before deleting a file from the filesystem\",\n	    \"defaultValue\": \"60000\"\n	  },\n	  {\n	    \"id\": \"flush.messages\",\n	    \"description\": \"This setting allows specifying an interval at which we will force an fsync of data written to the log. For example if this was set to 1 we would fsync after every message; if it were 5 we would fsync after every five messages. In general we recommend you not set this and use replication for durability and allow the operating system\'s background flush capabilities as it is more efficient. This setting can be overridden on a per-topic basis (see the per-topic configuration section).\",\n	    \"defaultValue\": \"9223372036854775807\"\n	  },\n	  {\n	    \"id\": \"flush.ms\",\n	    \"description\": \"This setting allows specifying a time interval at which we will force an fsync of data written to the log. For example if this was set to 1000 we would fsync after 1000 ms had passed. In general we recommend you not set this and use replication for durability and allow the operating system\'s background flush capabilities as it is more efficient.\",\n	    \"defaultValue\": \"9223372036854775807\"\n	  },\n	  {\n	    \"id\": \"follower.replication.throttled.replicas\",\n	    \"description\": \"A list of replicas for which log replication should be throttled on the follower side. The list should describe a set of replicas in the form [PartitionId]:[BrokerId],[PartitionId]:[BrokerId]:... or alternatively the wildcard \'*\' can be used to throttle all replicas for this topic.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"index.interval.bytes\",\n	    \"description\": \"This setting controls how frequently Kafka adds an index entry to its offset index. The default setting ensures that we index a message roughly every 4096 bytes. More indexing allows reads to jump closer to the exact position in the log but makes the index larger. You probably don\'t need to change this.\",\n	    \"defaultValue\": \"4096\"\n	  },\n	  {\n	    \"id\": \"leader.replication.throttled.replicas\",\n	    \"description\": \"A list of replicas for which log replication should be throttled on the leader side. The list should describe a set of replicas in the form [PartitionId]:[BrokerId],[PartitionId]:[BrokerId]:... or alternatively the wildcard \'*\' can be used to throttle all replicas for this topic.\",\n	    \"defaultValue\": \"\"\n	  },\n	  {\n	    \"id\": \"max.compaction.lag.ms\",\n	    \"description\": \"The maximum time a message will remain ineligible for compaction in the log. Only applicable for logs that are being compacted.\",\n	    \"defaultValue\": \"9223372036854775807\"\n	  },\n	  {\n	    \"id\": \"max.message.bytes\",\n	    \"description\": \"The largest record batch size allowed by Kafka (after compression if compression is enabled). If this is increased and there are consumers older than 0.10.2, the consumers\' fetch size must also be increased so that they can fetch record batches this large. In the latest message format version, records are always grouped into batches for efficiency. In previous message format versions, uncompressed records are not grouped into batches and this limit only applies to a single record in that case.\",\n	    \"defaultValue\": \"1048588\"\n	  },\n	  {\n	    \"id\": \"message.format.version\",\n	    \"description\": \"[DEPRECATED] Specify the message format version the broker will use to append messages to the logs. The value of this config is always assumed to be `3.0` if `inter.broker.protocol.version` is 3.0 or higher (the actual config value is ignored). Otherwise, the value should be a valid ApiVersion. Some examples are: 0.10.0, 1.1, 2.8, 3.0. By setting a particular message format version, the user is certifying that all the existing messages on disk are smaller or equal than the specified version. Setting this value incorrectly will cause consumers with older versions to break as they will receive messages with a format that they don\'t understand.\",\n	    \"defaultValue\": \"3.0-IV1\"\n	  },\n	  {\n	    \"id\": \"message.timestamp.difference.max.ms\",\n	    \"description\": \"The maximum difference allowed between the timestamp when a broker receives a message and the timestamp specified in the message. If message.timestamp.type=CreateTime, a message will be rejected if the difference in timestamp exceeds this threshold. This configuration is ignored if message.timestamp.type=LogAppendTime.\",\n	    \"defaultValue\": \"9223372036854775807\"\n	  },\n	  {\n	    \"id\": \"message.timestamp.type\",\n	    \"description\": \"Define whether the timestamp in the message is message create time or log append time. The value should be either `CreateTime` or `LogAppendTime`\",\n	    \"defaultValue\": \"CreateTime\"\n	  },\n	  {\n	    \"id\": \"min.cleanable.dirty.ratio\",\n	    \"description\": \"This configuration controls how frequently the log compactor will attempt to clean the log (assuming log compaction is enabled). By default we will avoid cleaning a log where more than 50% of the log has been compacted. This ratio bounds the maximum space wasted in the log by duplicates (at 50% at most 50% of the log could be duplicates). A higher ratio will mean fewer, more efficient cleanings but will mean more wasted space in the log. If the max.compaction.lag.ms or the min.compaction.lag.ms configurations are also specified, then the log compactor considers the log to be eligible for compaction as soon as either: (i) the dirty ratio threshold has been met and the log has had dirty (uncompacted) records for at least the min.compaction.lag.ms duration, or (ii) if the log has had dirty (uncompacted) records for at most the max.compaction.lag.ms period.\",\n	    \"defaultValue\": \"0.5\"\n	  },\n	  {\n	    \"id\": \"min.compaction.lag.ms\",\n	    \"description\": \"The minimum time a message will remain uncompacted in the log. Only applicable for logs that are being compacted.\",\n	    \"defaultValue\": \"0\"\n	  },\n	  {\n	    \"id\": \"min.insync.replicas\",\n	    \"description\": \"When a producer sets acks to \'all\' (or \'-1\'), this configuration specifies the minimum number of replicas that must acknowledge a write for the write to be considered successful. If this minimum cannot be met, then the producer will raise an exception (either NotEnoughReplicas or NotEnoughReplicasAfterAppend). When used together, min.insync.replicas and acks allow you to enforce greater durability guarantees. A typical scenario would be to create a topic with a replication factor of 3, set min.insync.replicas to 2, and produce with acks of \'all\'. This will ensure that the producer raises an exception if a majority of replicas do not receive a write.\",\n	    \"defaultValue\": \"1\"\n	  },\n	  {\n	    \"id\": \"preallocate\",\n	    \"description\": \"True if we should preallocate the file on disk when creating a new log segment.\",\n	    \"defaultValue\": \"false\"\n	  },\n	  {\n	    \"id\": \"retention.bytes\",\n	    \"description\": \"This configuration controls the maximum size a partition (which consists of log segments) can grow to before we will discard old log segments to free up space if we are using the \'delete\' retention policy. By default there is no size limit only a time limit. Since this limit is enforced at the partition level, multiply it by the number of partitions to compute the topic retention in bytes.\",\n	    \"defaultValue\": \"-1\"\n	  },\n	  {\n	    \"id\": \"retention.ms\",\n	    \"description\": \"This configuration controls the maximum time we will retain a log before we will discard old log segments to free up space if we are using the \'delete\' retention policy. This represents an SLA on how soon consumers must read their data. If set to -1, no time limit is applied.\",\n	    \"defaultValue\": \"604800000\"\n	  },\n	  {\n	    \"id\": \"segment.bytes\",\n	    \"description\": \"This configuration controls the segment file size for the log. Retention and cleaning is always done a file at a time so a larger segment size means fewer files but less granular control over retention.\",\n	    \"defaultValue\": \"1073741824\"\n	  },\n	  {\n	    \"id\": \"segment.index.bytes\",\n	    \"description\": \"This configuration controls the size of the index that maps offsets to file positions. We preallocate this index file and shrink it only after log rolls. You generally should not need to change this setting.\",\n	    \"defaultValue\": \"10485760\"\n	  },\n	  {\n	    \"id\": \"segment.jitter.ms\",\n	    \"description\": \"The maximum random jitter subtracted from the scheduled segment roll time to avoid thundering herds of segment rolling\",\n	    \"defaultValue\": \"0\"\n	  },\n	  {\n	    \"id\": \"segment.ms\",\n	    \"description\": \"This configuration controls the period of time after which Kafka will force the log to roll even if the segment file isn\'t full to ensure that retention can delete or compact old data.\",\n	    \"defaultValue\": \"604800000\"\n	  },\n	  {\n	    \"id\": \"unclean.leader.election.enable\",\n	    \"description\": \"Indicates whether to enable replicas not in the ISR set to be elected as leader as a last resort, even though doing so may result in data loss.\",\n	    \"defaultValue\": \"false\"\n	  },\n	  {\n	    \"id\": \"message.downconversion.enable\",\n	    \"description\": \"This configuration controls whether down-conversion of message formats is enabled to satisfy consume requests. When set to false, broker will not perform down-conversion for consumers expecting an older message format. The broker responds with UNSUPPORTED_VERSION error for consume requests from such older clients. This configurationdoes not apply to any message format conversion that might be required for replication to followers.\",\n	    \"defaultValue\": \"true\"\n	  }\n	]\n}','administrator'),('MASTER-Configuration-3','2026-07-05 18:39:22','RtdbMaintainer config','default','YAML','Scheduler','SCHEDULING','2026-07-05 18:39:22','RtdbMaintainer: \n  cron: \"0 59 23 ? * * *\"\n  timeout: 24\n  timeUnit: HOURS\nBackupMinio:\n  cron: \"0 59 23 ? * * *\"\n  timeout: 24\n  timeUnit: HOURS','administrator'),('MASTER-Configuration-30','2026-07-05 18:39:23','Data class with general rules','default','YAML','GeneralDataClass','DATACLASS','2026-07-05 18:39:23','#General Data Class\ndataclass:\n    name: generalDataClass\n    description: general rules\n    dataclassrules:\n        -   ruletype: property\n            rulename: toUpperCase\n            changes:\n                -\n                    order: 0\n                    name: mayus\n                    script: |-\n                        groovy\n                        return value.toUpperCase();\n        -   ruletype: property\n            rulename: toLowerCase\n            changes:\n                -\n                    order: 0\n                    name: minus\n                    script: |-\n                        groovy\n                        return value.toLowerCase();\n        -   ruletype: property\n            rulename: toDatetoString\n            changes:\n                -\n                    order: 0\n                    name: toDate\n                    script: |-\n                        javascript\n                        return value.toDate(\'dd.mm.yy\').toString(\'yyyy-mm-dd\');\n        -   ruletype: property\n            rulename: dniformat\n            validations:\n                -   \n                    name: dniformat\n                    script: |-\n                        javascript\n                        var regular_exp = /^\\d{8}[a-zA-Z]$/;\n                        if(regular_exp.test(value) === true){\n                            var numero = value.substr(0,value.length-1);\n                            var letr = value.substr(value.length-1,1);\n                            var num = numero % 23;\n                            var letra=\'TRWAGMYFPDXBNJZSQVHLCKET\';\n                            letra=letra.substring(num,num+1);\n                            if (letra!==letr.toUpperCase()) {\n                                return numero + letra;\n                            } else{\n                                return true;\n                            }\n                        } else{\n                         return false;\n                        }\n                    error: error\n                    errormsg: ${value} no es un formato vÃ¡lido de dni\n        -   ruletype: property\n            rulename: comunidadesEsp\n            changes:\n                -\n                    order: 0\n                    name: comMadrid\n                    script: |-\n                        groovy\n                        return value.replace(\"Madrid\", \"Comunidad de Madrid\");\n                -\n                    order: 1\n                    name: comValencia\n                    script: |-\n                        groovy\n                        return value.replace(\"Valencia\", \"Comunidad Valenciana\");\n                -\n                    order: 2\n                    name: Asturias\n                    script: |-\n                        groovy\n                        return value.replace(\"Asturias\", \"Principado de Asturias\");\n                -\n                    order: 3\n                    name: Murcia\n                    script: |-\n                        groovy\n                        return value.replace(\"Murcia\", \"RegiÃ³n de Murcia\");\n            validations:\n                -   \n                    name: comunidades\n                    script: |-\n                        groovy\n                        def comunidades = [\"AndalucÃ­a\", \"AragÃ³n\", \"Canarias\", \"Cantabria\", \"Castilla y LeÃ³n\", \"Castilla-La Mancha\", \"CataluÃ±a\", \"Ceuta\", \n                            \"Comunidad Valenciana\",\"Comunidad de Madrid\", \"Extremadura\", \"Galicia\", \"Islas Baleares\", \"La Rioja\", \"Melilla\", \"Navarra\", \"PaÃ­s Vasco\", \"Principado de Asturias\", \n                            \"RegiÃ³n de Murcia\"] as String[];\n                        return comunidades.contains(value);\n                    error: error\n                    errormsg: ${value} no es una comunidad espaÃ±ola\n        -   ruletype: property\n            rulename: provinciasEsp\n            validations:\n                -   \n                    name: provincias\n                    script: |-\n                        javascript\n                        var provincias = [\'Alava\',\'Albacete\',\'Alicante\',\'AlmerÃ­a\',\'Asturias\',\'Ãvila\',\'Badajoz\',\'Barcelona\',\'Burgos\',\'CÃ¡ceres\',\'CÃ¡diz\',\'Cantabria\',\'CastellÃ³n\',\'Ciudad Real\',\'CÃ³rdoba\',\'La CoruÃ±a\',\n                        \'Cuenca\',\'Gerona\',\'Granada\',\'Guadalajara\',\'GuipÃºzcoa\',\'Huelva\',\'Huesca\',\'Islas Baleares\',\'JaÃ©n\',\'LeÃ³n\',\'LÃ©rida\',\'Lugo\',\'Madrid\',\'MÃ¡laga\',\'Murcia\',\'Navarra\',\'Ourense\',\'Palencia\',\'Las Palmas\',\'Pontevedra\',\n                        \'La Rioja\',\'Salamanca\',\'Segovia\',\'Sevilla\',\'Soria\',\'Tarragona\',\'Santa Cruz de Tenerife\',\'Teruel\',\'Toledo\',\'Valencia\',\'Valladolid\',\'Vizcaya\',\'Zamora\',\'Zaragoza\']; \n                        return provincias.indexOf(value) != -1;\n                    error: warning\n                    errormsg: ${value} no es una provincia espaÃ±ola\n        -   \n            ruletype: entity\n            rulename: adultAge\n            changes:\n                -\n                    name: pediatra\n                    order: 0\n                    condition: rawdata.age > 17\n                    effect: rawdata.adult = \'yes\'\n                    else: rawdata.adult = \'no\'\n            validations:\n                -\n                    name: isAdult\n                    error: error\n                    errormsg: El paciente ${rawdata.dni} es menor de 18\n                    script: |- \n                        javascript\n                        var json = JSON.parse(rawdata); \n                        if(json.age > 17){\n                            return true;\n                        } else {\n                            return false;\n                        }','administrator'),('MASTER-Configuration-31','2026-07-05 18:39:23','Presto connection properties.','default','JSON','Presto Connection Properties','PRESTO_PROPERTIES','2026-07-05 18:39:23','{\n	\"accumulo\":[\n	  {\n	    \"name\": \"accumulo.instance\",\n	    \"description\": \"Name of the Accumulo instance.\",\n	    \"defaultValue\": \"\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"accumulo.zookeepers\",\n	    \"description\": \"ZooKeeper connect string.\",\n	    \"defaultValue\": \"\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"accumulo.username\",\n	    \"description\": \"Accumulo user for Presto.\",\n	    \"defaultValue\": \"\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"accumulo.password\",\n	    \"description\": \"Accumulo password for user.\",\n	    \"defaultValue\": \"\",\n	    \"required\": true,\n	    \"encrypt\": true\n	  },\n	  {\n	    \"name\": \"accumulo.zookeeper.metadata.root\",\n	    \"description\": \"Root znode for storing metadata. Only relevant if using default Metadata Manager.\",\n	    \"defaultValue\": \"/presto-accumulo\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"accumulo.cardinality.cache.size\",\n	    \"description\": \"Sets the size of the index cardinality cache.\",\n	    \"defaultValue\": \"100000\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"accumulo.cardinality.cache.expire.duration\",\n	    \"description\": \"Sets the expiration duration of the cardinality cache.\",\n	    \"defaultValue\": \"5m\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  }\n	],\n	\"bigquery\": [\n	  {\n	    \"name\": \"bigquery.project-id\",\n	    \"description\": \"Google Cloud project ID.\",\n	    \"defaultValue\": \"\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.parent-project\",\n	    \"description\": \"Google Cloud parent project ID.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.parallelism\",\n	    \"description\": \"The number of partitions to split the data.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.views-enabled\",\n	    \"description\": \"Enable BigQuery connector to read views.\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.view-materialization-project \",\n	    \"description\": \"The project where the materialized view is going to be created.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.view-materialization-dataset\",\n	    \"description\": \"The dataset where the materialized view is going to be created.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.max-read-rows-retries\",\n	    \"description\": \"The number of retries in case of retryable server issues.\",\n	    \"defaultValue\": \"3\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"bigquery.credentials-key\",\n	    \"description\": \"Credentials key (base64 encoded).\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": true\n	  },\n	  {\n	    \"name\": \"bigquery.credentials-file\",\n	    \"description\": \"JSON credentials file path.\",\n	    \"defaultValue\": \"\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  }\n	],\n	\"blackhole\": [],\n	\"cassandra\": [\n	  {\n	    \"name\": \"cassandra.contact-points\",\n	    \"description\": \"Comma-separated list of hosts in a Cassandra cluster. The Cassandra driver will use these contact points to discover cluster topology. At least one Cassandra host is required.\",\n	    \"defaultValue\": \"hostname\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.native-protocol-port\",\n	    \"description\": \"The Cassandra server port running the native client protocol (defaults to 9042).\",\n	    \"defaultValue\": \"9042\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.consistency-level\",\n	    \"description\": \"Consistency levels in Cassandra refer to the level of consistency to be used for both read and write operations. More information about consistency levels can be found in the Cassandra consistency documentation. This property defaults to a consistency level of ONE. Possible values include ALL, EACH_QUORUM, QUORUM, LOCAL_QUORUM, ONE, TWO, THREE, LOCAL_ONE, ANY, SERIAL, LOCAL_SERIAL.\",\n	    \"defaultValue\": \"ONE\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.allow-drop-table\",\n	    \"description\": \"Set to true to allow dropping Cassandra tables from Presto via DROP TABLE (defaults to false).\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.username\",\n	    \"description\": \"Username used for authentication to the Cassandra cluster. This is a global setting used for all connections, regardless of the user who is connected to Presto.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.password\",\n	    \"description\": \"Password used for authentication to the Cassandra cluster. This is a global setting used for all connections, regardless of the user who is connected to Presto.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": true\n	  },\n	  {\n	    \"name\": \"cassandra.protocol-version\",\n	    \"description\": \"It is possible to override the protocol version for older Cassandra clusters. This property defaults to V3. Possible values include V2, V3 and V4.\",\n	    \"defaultValue\": \"v3\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.fetch-size\",\n	    \"description\": \"Number of rows fetched at a time in a Cassandra query.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.partition-size-for-batch-select\",\n	    \"description\": \"Number of partitions batched together into a single select for a single partition key column table.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.split-size\",\n	    \"description\": \"Number of keys per split when querying Cassandra.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.splits-per-node\",\n	    \"description\": \"Number of splits per node. By default, the values from the system.size_estimates table are used. Only override when connecting to Cassandra versions < 2.1.5, which lacks the system.size_estimates table.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.client.read-timeout\",\n	    \"description\": \"Maximum time the Cassandra driver will wait for an answer to a query from one Cassandra node. Note that the underlying Cassandra driver may retry a query against more than one node in the event of a read timeout. Increasing this may help with queries that use an index.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.client.connect-timeout\",\n	    \"description\": \"Maximum time the Cassandra driver will wait to establish a connection to a Cassandra node. Increasing this may help with heavily loaded Cassandra clusters.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.client.so-linger\",\n	    \"description\": \"Number of seconds to linger on close if unsent data is queued. If set to zero, the socket will be closed immediately. When this option is non-zero, a socket will linger that many seconds for an acknowledgement that all data was written to a peer. This option can be used to avoid consuming sockets on a Cassandra server by immediately closing connections when they are no longer needed.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.retry-policy\",\n	    \"description\": \"Policy used to retry failed requests to Cassandra. This property defaults to DEFAULT. Using BACKOFF may help when queries fail with â€œnot enough replicasâ€. The other possible values are DOWNGRADING_CONSISTENCY and FALLTHROUGH.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.use-dc-aware\",\n	    \"description\": \"Set to true to use DCAwareRoundRobinPolicy (defaults to false).\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.dc-aware.local-dc\",\n	    \"description\": \"The name of the local datacenter for DCAwareRoundRobinPolicy.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.dc-aware.used-hosts-per-remote-dc\",\n	    \"description\": \"Uses the provided number of host per remote datacenter as failover for the local hosts for DCAwareRoundRobinPolicy.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.dc-aware.allow-remote-dc-for-local\",\n	    \"description\": \"Set to true to allow to use hosts of remote datacenter for local consistency level.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.use-token-aware\",\n	    \"description\": \"Set to true to use TokenAwarePolicy (defaults to false).\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.shuffle-replicas\",\n	    \"description\": \"Set to true to use TokenAwarePolicy with shuffling of replicas (defaults to false).\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.use-white-list\",\n	    \"description\": \"Set to true to use WhiteListPolicy (defaults to false).\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.load-policy.white-list.addresses\",\n	    \"description\": \"Comma-separated list of hosts for WhiteListPolicy.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.no-host-available-retry-timeout\",\n	    \"description\": \"Retry timeout for NoHostAvailableException (defaults to 1m).\",\n	    \"defaultValue\": \"1m\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.speculative-execution.limit\",\n	    \"description\": \"The number of speculative executions (defaults to 1).\",\n	    \"defaultValue\": \"1\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.speculative-execution.delay\",\n	    \"description\": \"The delay between each speculative execution (defaults to 500ms).\",\n	    \"defaultValue\": \"500ms\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.tls.enabled\",\n	    \"description\": \"Whether TLS security is enabled (defaults to false).\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.tls.keystore-path\",\n	    \"description\": \"Path to the PEM or JKS key store.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.tls.truststore-path\",\n	    \"description\": \"Path to the PEM or JKS trust store.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"cassandra.tls.keystore-password\",\n	    \"description\": \"Password for the key store.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": true\n	  },\n	  {\n	    \"name\": \"cassandra.tls.truststore-password\",\n	    \"description\": \"Password for the trust store.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": true\n	  }\n	],\n	\"clickhouse\": [\n	  {\n	    \"name\": \"clickhouse.connection-url\",\n	    \"description\": \"Defines the connection information and parameters to pass to the JDBC driver.\",\n	    \"defaultValue\": \"jdbc:clickhouse://hostname:8123/\",\n	    \"required\": true,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"clickhouse.connection-user\",\n	    \"description\": \"Username for the connection.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"clickhouse.connection-password\",\n	    \"description\": \"Password for the connection.\",\n	    \"defaultValue\": \"\",\n	    \"required\": false,\n	    \"encrypt\": true\n	  },\n	  {\n	    \"name\": \"clickhouse.map-string-as-varchar\",\n	    \"description\": \"When creating a table, support the clickhouse data type String.\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  },\n	  {\n	    \"name\": \"clickhouse.allow-drop-table\",\n	    \"description\": \"Allow delete table operation.\",\n	    \"defaultValue\": \"false\",\n	    \"required\": false,\n	    \"encrypt\": false\n	  }\n	],\n	\"delta\": [\n	  {\n	    \"name\": \"hive.metastore.uri\",\n	    \"description\": \"The URI(s) of the Hive metastore to connect to using the Thrift protocol. If multiple URIs are provided, the first URI is used by default and the rest of the URIs are fallback metastores. Example: thrift://192.0.2.3:9083 or thrift://192.0.2.3:9083,thrift:/