n\\n\\n<div class=\\\"page-title-box d-flex align-items-center  gadget-header\\\">\\n\\t<!--<h4 class=\\\"mb-0 font-size-16\\\" style=\\\"font-family: Soho;font-size:1rem;\\\">QUERY METRICS</h4>-->\\n\\t<div style=\\\"display: inline-grid;\\\">\\n\\t\\t<label for=\\\"name\\\" class=\\\"ods-form-item__label\\\">Entity</label>\\n\\t\\t<el-select v-model=\\\"valueEntity\\\" multiple filterable clearable collapse-tags size=\\\"mini\\\"\\n\\t\\t\\tstyle=\\\"margin-left: 20px;width: 240px;\\\" placeholder=\\\"Select\\\">\\n\\t\\t\\t<el-option v-for=\\\"item in optionsEntity\\\" :key=\\\"item.value\\\" :label=\\\"item.label\\\" :value=\\\"item.value\\\">\\n\\t\\t\\t</el-option>\\n\\t\\t</el-select>\\n\\t</div>\\n\\t<div style=\\\"display: inline-grid;\\\">\\n\\t\\t<label for=\\\"name\\\" class=\\\"ods-form-item__label\\\">Source</label>\\n\\t\\t<el-select v-model=\\\"valueSource\\\" multiple filterable clearable collapse-tags size=\\\"mini\\\"\\n\\t\\t\\tstyle=\\\"margin-left: 20px;width: 240px;\\\" placeholder=\\\"Select\\\">\\n\\t\\t\\t<el-option v-for=\\\"item in optionsSource\\\" :key=\\\"item.value\\\" :label=\\\"item.label\\\" :value=\\\"item.value\\\">\\n\\t\\t\\t</el-option>\\n\\t\\t</el-select>\\n\\t</div>\\n\\t<div style=\\\"display: inline-grid;\\\">\\n\\t\\t<label for=\\\"name\\\" class=\\\"ods-form-item__label\\\">Query Type</label>\\n\\t\\t<el-select v-model=\\\"valueQueryType\\\" multiple filterable clearable collapse-tags size=\\\"mini\\\"\\n\\t\\t\\tstyle=\\\"margin-left: 20px;width: 240px;\\\" placeholder=\\\"Select\\\">\\n\\t\\t\\t<el-option v-for=\\\"item in optionsQueryType\\\" :key=\\\"item.value\\\" :label=\\\"item.label\\\" :value=\\\"item.value\\\">\\n\\t\\t\\t</el-option>\\n\\t\\t</el-select>\\n\\t</div>\\n\\n\\t<div style=\\\"display: inline-grid;\\\">\\n\\t\\t<label for=\\\"name\\\" class=\\\"ods-form-item__label\\\">Users</label>\\n\\t\\t<el-select v-model=\\\"valueUsers\\\" multiple filterable clearable collapse-tags size=\\\"mini\\\"\\n\\t\\t\\tstyle=\\\"margin-left: 20px;width: 240px;\\\" placeholder=\\\"Select\\\">\\n\\t\\t\\t<el-option v-for=\\\"item in optionsUsers\\\" :key=\\\"item.value\\\" :label=\\\"item.label\\\" :value=\\\"item.value\\\">\\n\\t\\t\\t</el-option>\\n\\t\\t</el-select>\\n\\t</div>\\n\\t<div style=\\\"display: inline-grid;\\\">\\n\\t\\t<label for=\\\"name\\\" class=\\\"ods-form-item__label\\\">Status</label>\\n\\t\\t<el-select v-model=\\\"valueStatus\\\" multiple filterable clearable collapse-tags size=\\\"mini\\\"\\n\\t\\t\\tstyle=\\\"margin-left: 20px;width: 240px;\\\" placeholder=\\\"Select\\\">\\n\\t\\t\\t<el-option v-for=\\\"item in optionsStatus\\\" :key=\\\"item.value\\\" :label=\\\"item.label\\\" :value=\\\"item.value\\\">\\n\\t\\t\\t</el-option>\\n\\t\\t</el-select>\\n\\t</div>\\n\\t<div style=\\\"display: flex; justify-content: flex-end;width: 20%;margin-top:19px;\\\">\\n\\t\\t<el-button type=\\\"primary\\\" icon=\\\"el-icon-search\\\" v-on:click=\\\"search\\\" size=\\\"mini\\\">Search</el-button>\\n\\t\\t<el-button type=\\\"text\\\" v-on:click=\\\"reset\\\" size=\\\"mini\\\">Reset</el-button>\\n\\t</div>\\n\\n</div>\",\n              \"nomargin\": false,\n              \"contentcode\": \"//Write your Vue with ODS JSON controller code here\\n//Focus here and F11 to full screen editor\\n//This function will be call once to init components\\nvm.vueconfig = {\\n  el: document.querySelector(\'#\' + vm.id + \' vuetemplate .gadget-header\'),\\n  data: {\\n    ds: [],\\n\\n    optionsEntity: [],\\n    valueEntity: [],\\n\\n    optionsQueryType: [],\\n    valueQueryType: [],\\n\\n    optionsQuery: [],\\n    valueQuery: [],\\n\\n    optionsSource: [],\\n    valueSource: [],\\n\\n    optionsStatus: [],\\n    valueStatus: [],\\n\\n    optionsUsers: [],\\n    valueUsers: [],\\n\\n\\n    size: \'hecto\',\\n    placeholder: \'Select\',\\n    selectLabel: \'Organization\',\\n    name: \'orgid\',\\n    disabled: false,\\n    clearable: true,\\n    loading: false,\\n    loadingText: \'Loading\',\\n    noMatchText: \'No matching data\',\\n    noDataText: \'No data\',\\n    popperClass: \'\',\\n    filterable: false,\\n    allowCreate: false,\\n    multiple: true,\\n    multipleLimit: 0,\\n    collapseTags: true,\\n    labelOptionGroup: null,\\n    disabledOptionGroup: null,\\n    valueOption: \'\',\\n    label: \'\',\\n    disabledOption: false,\\n    remote: false,\\n    reserveKeyword: false,\\n    defaultFirstOption: false,\\n    popperAppendToBody: true,\\n    automaticDropdown: false,\\n    accentBlock: false,\\n    rtl: false\\n  },\\n  methods: {\\n    drawVueComponent: function (newData, oldData) {\\n\\n    },\\n    resizeEvent: function () {\\n      //Resize event\\n    },\\n    destroyVueComponent: function () {\\n      vm.vueapp.$destroy();\\n    },\\n    receiveValue: function (data) {\\n      //data received from datalink\\n    },\\n    sendValue: vm.sendValue,\\n    sendFilter: vm.sendFilter,\\n    gridsterClass(cssClass) {\\n      this.$el.parentElement.parentElement.parentElement.parentElement.className += \' \' + cssClass\\n    },\\n    \\n\\n\\n    search: function (e) {\\n      for (var i = 0; i < vm.filters.length; i++) {\\n        if (vm.filters[i].id == \'entity\') {\\n          vm.filters[i].data.optionsSelected = this.valueEntity;\\n        }\\n        else if (vm.filters[i].id == \'user\') {\\n          vm.filters[i].data.optionsSelected = this.valueUsers;\\n        }\\n        else if (vm.filters[i].id == \'source\') {\\n          vm.filters[i].data.optionsSelected = this.valueSource;\\n        }\\n        else if (vm.filters[i].id == \'status\') {\\n          vm.filters[i].data.optionsSelected = this.valueStatus;\\n        } else if (vm.filters[i].id == \'queryType\') {\\n          vm.filters[i].data.optionsSelected = this.valueQueryType;\\n        }\\n      }\\n      vm.sendFilters();\\n    },\\n    reset: function (e) {\\n\\n      this.valueEntity = [];\\n      this.valueQueryType = [];\\n      this.valueSource = [];\\n      this.valueStatus = [];\\n      this.valueUsers = [];\\n      this.search();\\n    },\\n\\n\\n  },\\n  mounted() {\\n    var that = this;\\n    this.gridsterClass(\'no-shadow\');\\n\\n    //ENTITY\\n    vm.get(\\\"QueryMetrics_distinct_entity\\\").then(\\n      function (newData) {\\n        that.optionsEntity = [];\\n        if (typeof newData !== \'undefined\' && newData != null && newData.length > 0) {\\n          for (var i = 0; i < newData.length; i++) {\\n            that.optionsEntity.push({ value: newData[i].entity, label: newData[i].entity });\\n          }\\n        }\\n      }\\n    );\\n\\n    //QUERY TYPE\\n    vm.get(\\\"QueryMetrics_distinct_queryType\\\").then(\\n      function (newData) {\\n        that.optionsQueryType = [];\\n        if (typeof newData !== \'undefined\' && newData != null && newData.length > 0) {\\n          for (var i = 0; i < newData.length; i++) {\\n            that.optionsQueryType.push({ value: newData[i].queryType, label: newData[i].queryType });\\n          }\\n        }\\n      }\\n    );\\n    \\n   \\n\\n    //SOURCE\\n    vm.get(\\\"QueryMetrics_distinct_source\\\").then(\\n      function (newData) {\\n        that.optionsSource = [];\\n        if (typeof newData !== \'undefined\' && newData != null && newData.length > 0) {\\n          for (var i = 0; i < newData.length; i++) {\\n            that.optionsSource.push({ value: newData[i].source, label: newData[i].source });\\n          }\\n        }\\n      }\\n    );\\n    //STATUS\\n    vm.get(\\\"QueryMetrics_distinct_status\\\").then(\\n      function (newData) {\\n        that.optionsStatus = [];\\n        if (typeof newData !== \'undefined\' && newData != null && newData.length > 0) {\\n          for (var i = 0; i < newData.length; i++) {\\n            that.optionsStatus.push({ value: newData[i].status, label: newData[i].status });\\n          }\\n        }\\n      }\\n    );\\n    //USERS\\n    vm.get(\\\"QueryMetrics_distinct_users\\\").then(\\n      function (newData) {\\n        that.optionsUsers = [];\\n        if (typeof newData !== \'undefined\' && newData != null && newData.length > 0) {\\n          for (var i = 0; i < newData.length; i++) {\\n            that.optionsUsers.push({ value: newData[i].user, label: newData[i].user });\\n          }\\n        }\\n      }\\n    );\\n\\n\\n\\n\\n  }\\n}\\n//Init Vue app\\nvm.vueapp = new Vue(vm.vueconfig);\",\n              \"subtype\": \"vueJS\",\n              \"datasource\": \"\",\n              \"x\": 0,\n              \"y\": 0,\n              \"header\": {\n                \"backgroundColor\": \"hsl(0, 0%, 100%)\",\n                \"enable\": false,\n                \"title\": {\n                  \"iconColor\": \"hsl( 206, 54%, 5%)\",\n                  \"icon\": \"\",\n                  \"text\": \"header\",\n                  \"textColor\": \"hsl(206,54%,5%)\"\n                },\n                \"height\": 40\n              },\n              \"id\": \"livehtml_1669717583701\",\n              \"customMenuOptions\": [],\n              \"cols\": 50\n            },\n            {\n              \"border\": {\n                \"color\": \"hsl(0, 0%, 90%)\",\n                \"width\": 0,\n                \"radius\": 5\n              },\n              \"padding\": 0,\n              \"backgroundColor\": \"white\",\n              \"notshowDotsMenu\": true,\n              \"hideBadges\": true,\n              \"prettyTitle\": \"source_kpi_error (livehtml)\",\n              \"rows\": 3,\n              \"type\": \"livehtml\",\n              \"$$hashKey\": \"object:688\",\n              \"content\": \"<style>\\n .gadget-app { font-family: Poppins}\\n   gridster-item { box-shadow: 0 0.75rem 1.5rem rgb(18 38 63 / 3%); }\\n\\n\\n  .card {   margin-top: 0px; } \\n  \\n}\\n.card-body {\\n    flex: 1 1 auto;\\n    padding: 1rem;   \\n}\\n.mb-3 {\\n    margin-bottom: 1rem!important;\\n}\\n.align-items-center {\\n    align-items: center!important;\\n}\\n.d-flex {\\n    display: flex!important;\\n}\\n.avatar-xs {\\n    height: 2rem;\\n    width: 2rem;\\n}\\n.me-3 {\\n    margin-right: 1rem!important;\\n}\\n.font-size-14 {\\n    font-size: 14px!important;\\n     font-family: \'Poppins\'\\n}\\n.mb-0 {\\n    margin-bottom: 0!important;\\n}\\n.bg-primary.bg-soft {\\n    background-color: rgba(85,110,230,.25)!important;\\n}\\n.font-size-18 {\\n    font-size: 18px!important;\\n    font-family: \'Poppins\'\\n}\\n.avatar-title {\\n    align-items: center;\\n    background-color: #556ee6;\\n    color: #fff;\\n    display: flex;\\n    font-weight: 500;\\n    height: 100%;\\n    justify-content: center;\\n    width: 100%;\\n}\\n.rounded-circle {\\n    border-radius: 50%!important;\\n}\\n.text-primary {\\n    color: rgba(85,110,230,1)!important;\\n}\\n.ods-icon-xs { font-size: 1rem}\\n\\n.text-muted { \\n    color: #74788d!important;\\n}\\n.mt-4 {\\n    margin-top: 1.5rem!important;\\n}\\n.text-success {\\n    color: rgba(52,195,143,1)!important;\\n}\\n\\n.ods-kpi-number { font-size: 1.22rem; font-weight: 500; color: #333; margin-top: 0; margin-bottom: 0.5rem; font-weight: 500; line-height: 1.2;}\\n\\n.font-size-12 {\\n    font-size: 12px!important;\\n}\\n.badge-soft-success {\\n    color: #34c38f!important;\\n    background-color: rgba(52,195,143,.18)!important;\\n}\\n.badge-soft-warning {\\n    color: #f1b44c!important;\\n    background-color: rgba(241,180,76,.18)!important;\\n}\\n\\n.badge {\\n    display: inline-block;\\n    padding: 0.25em 0.4em;\\n    font-size: 75%;\\n    font-weight: 500;\\n    line-height: 1;\\n    color: #fff;\\n    text-align: center;\\n    white-space: nowrap;\\n    vertical-align: baseline;\\n    border-radius: 0.25rem;\\n}\\n.ms-2 {\\n    margin-left: 0.5rem!important;\\n}\\n\\n.text-truncate {\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n    font-size: 0.8125rem;\\n    margin-top: .2rem;\\n}\\n    .gadget-simplekpi {\\n      width: 100%;\\n      height: 100%;\\n      display: flex;\\n      justify-content: start;\\n      align-items: start;\\n      margin-top:0px;     \\n      font-family: \'Poppins\', sans-serif;\\n      overflow: hidden;     \\n    }\\n    \\n    .ods-icon-sm {font-size: 1.5rem }\\n    .avatar-sm {  height: 3rem; width: 3rem; }\\n    .align-items-right { justify-content: end; }\\n\\n    .skeleton {\\n      display: grid;\\n      grid-template: 1fr 1fr/25% 1fr;\\n      gap: calc(1rem * 0.5);\\n      width: clamp(275px, 20vmin, 10rem);\\n      padding: 1rem;\\n      border: 0px solid rgba(37, 38, 39, 0.1);\\n      border-radius: calc(1rem * 0.5);\\n      background-color:  hsl(0 0% 0% / 0%);\\n    }\\n\\n    .skeleton__block {\\n      background: linear-gradient(-75deg, transparent 40%, hsl(0 0% 100% / 40%), transparent 60%) 0 0/200% 100%, hsl(0 0% 0% / 12%);\\n      border-radius: calc(1rem * 0.5);\\n      animation: load 2s infinite linear;\\n      background-attachment: fixed;\\n    }\\n\\n    @keyframes load {\\n      to {\\n        background-position: 200% 0;\\n      }\\n    }\\n    .skeleton__block:first-of-type {\\n      grid-row: 1/-1;\\n      aspect-ratio: 1;\\n    }\\n\\n  .bg-kpi {\\n    background-color: rgb(171 121 13 / 25%)!important;\\n  }\\n\\n  .framework__kpi-text {\\n      font-size: 0.85rem;\\n      line-height: 24px;       \\n      white-space: nowrap;\\n  }\\n\\n  .framework__downloads abbr { font-size: 75%}\\n\\n \\n\\n    .avatar-title {\\n      box-shadow: 0 0 0 rgba(204,169,44, 0.4);\\n      animation: pulse 2s infinite;\\n    }\\n\\n    \\n    @-webkit-keyframes pulse {\\n      0% {\\n        -webkit-box-shadow: 0 0 0 0 rgba(204,169,44, 0.4);\\n      }\\n      70% {\\n          -webkit-box-shadow: 0 0 0 10px rgba(204,169,44, 0);\\n      }\\n      100% {\\n          -webkit-box-shadow: 0 0 0 0 rgba(204,169,44, 0);\\n      }\\n    }\\n    @keyframes pulse {\\n      0% {\\n        -moz-box-shadow: 0 0 0 0 rgba(204,169,44, 0.4);\\n        box-shadow: 0 0 0 0 rgba(204,169,44, 0.4);\\n      }\\n      70% {\\n 