Start.format(format))\\n\\t\\t\\t\\tdateStart.add(1, \'day\')\\n\\t\\t\\t}\\n\\t\\t\\tconsole.log(\'Days: \', days)\\n\\t\\t\\treturn days\\n\\t\\t},\\n\\t\\t// TIME FORMATTER for AXIS \\n\\t\\taxisFormatter(data, type) {\\n\\t\\t\\tmoment.locale(this.timeSerie.locale || \'en\')\\n\\t\\t\\tvar formattedData = data || []\\n\\t\\t\\tvar currentYear = moment().year()\\n\\t\\t\\tif (data.length === 0) { return data }\\n\\t\\t\\t// making format\\n\\t\\t\\tvar yearF = \'YYYY\'\\n\\t\\t\\tvar monthFY = \'MMM YY\'\\n\\t\\t\\tvar monthF = \'MMM\'\\n\\t\\t\\tvar dayFY = \'DD MM YY\'\\n\\t\\t\\tvar dayF = \'DDD DD MM\'\\n\\t\\t\\tvar hour = \'HH\'\\n\\t\\t\\tvar formattedData = data.map(function (item) {\\n\\t\\t\\t\\tif (type === \'Y\') {\\n\\t\\t\\t\\t\\treturn item\\n\\t\\t\\t\\t} else if (type === \'M\') {\\n\\t\\t\\t\\t\\tif (currentYear === moment(item, \'YYYYMM\').year()) { return moment(item, \'YYYYMM\').format(\'MMM\') } else { return moment(item, \'YYYYMM\').format(\'MMM YY\') }\\n\\t\\t\\t\\t} else if (type === \'D\') {\\n\\t\\t\\t\\t\\tif (currentYear === moment(item, \'YYYYMMDD\').year()) { return moment(item, \'YYYYMMDD\').format(\'DD MMM\') } else { return moment(item, \'YYYYMMDD\').format(\'DD MMM YY\') }\\n\\t\\t\\t\\t} else if (type === \'H\') {\\n\\t\\t\\t\\t\\tif (currentYear === moment(item, \'YYYYMMDDHH\').year()) { return moment(item, \'YYYYMMDDHH\').format(\'HH DD\') } else { return moment(item, \'YYYYMMDDHH\').format(\'HH DD MM YY\') }\\n\\t\\t\\t\\t}\\n\\t\\t\\t})\\n\\n\\t\\t\\treturn formattedData\\n\\t\\t},\\n\\n\\t},\\n\\tmounted() {\\n\\t\\tvar chartDom = document.getElementById(\'barsworksorders010\');\\n\\t\\tthis.myChart = echarts.init(chartDom, null, { renderer: \'canvas\', useDirtyRect: false });\\n\\n\\t\\tthis.myChart.on(\'magictypechanged\', function (e) {\\n\\t\\t\\tif (e.currentType === \\\"line\\\") {\\n\\t\\t\\t\\tthis.typeSerie = \\\"line\\\"\\n\\t\\t\\t} else {\\n\\t\\t\\t\\tthis.typeSerie = \\\"bar\\\"\\n\\t\\t\\t}\\n\\t\\t});\\n\\