-top: 24px!important;\n    }\n\n    /*.el-table .cell {\n        font-size: 12px !important;\n    }\n\n    .el-table .el-table__cell {\n        padding: 5px 0 !important;\n    }*/\n\n\n    .download-icons-grey {\n          filter: invert(0%) sepia(0%) saturate(0%) hue-rotate(162deg) brightness(93%) contrast(88%);\n    }\n    .el-form-item__contentel-form-item__content {\n        display: none;\n    }\n\n\n\n    .row {\n        display: -ms-flexbox !important;\n        display: flex !important;\n        -ms-flex-wrap: wrap !important;\n        flex-wrap: wrap !important;\n        width:100% !important;\n        margin-right: -15px !important;\n        margin-left: -15px !important;\n    }\n    .col-md-12 {\n        -ms-flex: 0 0 100% !important;\n        flex: 0 0 100% !important;\n        max-width: 100% !important;\n    }\n    .col, .col-1, .col-10, .col-11, .col-12, .col-2, .col-3, .col-4, .col-5, .col-6, .col-7, .col-8, .col-9, .col-auto, .col-lg, .col-lg-1, .col-lg-10, .col-lg-11, .col-lg-12, .col-lg-2, .col-lg-3, .col-lg-4, .col-lg-5, .col-lg-6, .col-lg-7, .col-lg-8, .col-lg-9, .col-lg-auto, .col-md, .col-md-1, .col-md-10, .col-md-11, .col-md-12, .col-md-2, .col-md-3, .col-md-4, .col-md-5, .col-md-6, .col-md-7, .col-md-8, .col-md-9, .col-md-auto, .col-sm, .col-sm-1, .col-sm-10, .col-sm-11, .col-sm-12, .col-sm-2, .col-sm-3, .col-sm-4, .col-sm-5, .col-sm-6, .col-sm-7, .col-sm-8, .col-sm-9, .col-sm-auto, .col-xl, .col-xl-1, .col-xl-10, .col-xl-11, .col-xl-12, .col-xl-2, .col-xl-3, .col-xl-4, .col-xl-5, .col-xl-6, .col-xl-7, .col-xl-8, .col-xl-9, .col-xl-auto {\n        position: relative !important;\n        width: 100% !important;\n        padding-right: 15px !important;\n        padding-left: 15px !important;\n    }\n    /*label {\n        display: inline-block !important;\n        margin-bottom: 0.5rem !important;\n    }*/\n    .form-group {\n        margin-bottom: 1rem !important;\n    }\n\n    .form-control {\n        display: block !important;\n        width: 100%!important;\n        height: calc(1.5em + 0.75rem + 2px)!important;\n        padding: 0.375rem 0.75rem!important;\n        font-size: 1rem!important;\n        font-weight: 400!important;\n        line-height: 1.5!important;\n        color: #495057!important;\n        background-color: #fff!important;\n        background-clip: padding-box!important;\n        border: 1px solid #ced4da!important;\n        border-radius: 0.25rem!important;\n        transition: border-color .15s ease-in-out,box-shadow .15s ease-in-out!important;\n    }\n     /*optgroup, select, textarea {\n        margin: 0 !important;\n        font-family: inherit !important;\n        font-size: inherit !important;\n        line-height: inherit !important;\n    }\n    button, input {\n        margin: 0 !important;\n        font-family: inherit !important;\n\n        line-height: inherit !important;\n    }*/\n    .form-control:focus {\n        color: #495057 !important;\n        background-color: #fff !important;\n        border-color: #80bdff !important;\n        outline: 0 !important;\n        box-shadow: 0 0 0 0.2rem rgb(0 123 255 / 25%) !important;\n    }\n.float-right{\n    float: right;\n    margin-left: 10px!important;\n    margin-right: 10px!important;\n}\n\n</style>\n<div class=\"appgadget\" style=\"padding-left:10px;padding-right:10px;\">\n    <!-- entity selector -->\n    <ods-row >\n        <ods-col :span=\"8\">\n            <label class=\"control-label\">{{ $t(\"form.entity\") }}<span class=\"required\" aria-required=\"true\">\n                    *</span></label></br>\n            <ods-select  :disabled=\"showSelectOntology\" size=\"small\"  v-model=\"selectedOntology\"\n                @change=\"onChangeEntity($event)\" filterable :placeholder=\"$t(\'form.select\')\">\n                <ods-option v-for=\"onto in ontologies\" :key=\"onto.identification\" :label=\"onto.identification\"\n                    :value=\"onto.identification\">\n                </ods-option>\n            </ods-select >\n        </ods-col>\n        <!-- wizard switch -->\n        <ods-col v-if=\"typeGadget==\'withWizard\'||typeGadget==\'searchOnly\'\" :span=\"8\">\n            <ods-switch class=\"wizard-style\" v-model=\"showWizard\" @change=\"calculeTableheight\" :disabled=\"disabledWizard\"\n                :active-text=\"$t(\'form.show.wizard\')\"></ods-switch>\n        </ods-col>\n    </ods-row>\n        <ods-divider  direction=\"horizontal\"></ods-divider>\n    <ods-row>\n        </ods-row>\n    <!-- wizard  -->\n    <div class=\"crudWizard\" v-if=\"showWizard\">\n        <ods-row  type=\"flex\"\n            :gutter=\"10\">\n\n            <ods-col :xs=\"5\" :sm=\"5\" :md=\"5\" :lg=\"5\" :xl=\"5\">\n                <label class=\"control-label\">{{ $t(\"form.where\") }}</label></br>\n                <ods-select size=\"small\" v-model=\"selectWizard\" multiple collapse-tags :placeholder=\"$t(\'form.select\')\">\n                    <ods-option v-for=\"item in selectWizardOptions\" :key=\"item.value\" :label=\"item.label\"\n                        :value=\"item.value\">\n                    </ods-option>\n                </ods-select>\n            </ods-col>\n            <ods-col :xs=\"1\" :sm=\"1\" :md=\"1\" :lg=\"1\" :xl=\"1\" style=\"margin-top: 12px;\">\n                <ods-button  icon=\"ods-icon-plus\" type=\"primary\"  @click=\"dialogAddSelectVisibleFunction\"></ods-button>\n            </ods-col>\n            <ods-col :xs=\"5\" :sm=\"5\" :md=\"5\" :lg=\"5\" :xl=\"5\">\n                <label v-if=\"typeGadget!=\'searchOnly\'\" class=\"control-label\">{{ $t(\"form.orderby\") }}</label></br>\n                <ods-select v-if=\"typeGadget!=\'searchOnly\'\" size=\"small\" v-model=\"orderByWizard\" multiple collapse-tags\n                    :placeholder=\"$t(\'form.select\')\">\n                    <ods-option v-for=\"itemo in orderByWizardOptions\" :key=\"itemo.value\" :label=\"itemo.label\"\n                        :value=\"itemo.value\">\n                    </ods-option>\n                </ods-select>\n            </ods-col>\n            <ods-col :xs=\"1\" :sm=\"1\" :md=\"1\" :lg=\"1\" :xl=\"1\" style=\"margin-top: 12px;\">\n                <ods-button v-if=\"typeGadget!=\'searchOnly\'\" icon=\"ods-icon-plus\" type=\"primary\"\n                    @click=\"dialogAddOrderByVisibleFunction\"></ods-button>\n            </ods-col>\n            <ods-col :xs=\"3\" :sm=\"3\" :md=\"3\" :lg=\"3\" :xl=\"3\" style=\"min-width:100px\">\n                <label v-if=\"typeGadget!=\'searchOnly\'\" class=\"control-label\">{{ $t(\"form.max.value\") }}</label> </br>\n                <ods-input v-if=\"typeGadget!=\'searchOnly\'\" type=\"number\" size=\"small\" v-model=\"limitWizard\"\n                    controls-position=\"right\" :min=\"0\">\n                </ods-input>\n            </ods-col>\n            <ods-col :xs=\"3\" :sm=\"3\" :md=\"3\" :lg=\"3\" :xl=\"3\" style=\"min-width:100px\">\n                <label v-if=\"typeGadget!=\'searchOnly\'\" class=\"control-label\"> {{ $t(\"form.offset\") }} </label></br>\n                <ods-input v-if=\"typeGadget!=\'searchOnly\'\" type=\"number\" size=\"small\" v-model=\"offsetWizard\"\n                    controls-position=\"right\" :min=\"0\">\n                </ods-input>\n            </ods-col>\n\n            <ods-col :xs=\"1\" :sm=\"1\" :md=\"1\" :lg=\"1\" :xl=\"1\" style=\"min-width:100px; margin-top: 12px;\">\n\n                <ods-button   type=\"neutral\" class=\"float-right\" @click=\"resetWizard()\">{{ $t(\"form.reset\") }}\n                </ods-button>\n            </ods-col>\n            <ods-col :xs=\"1\" :sm=\"1\" :md=\"1\" :lg=\"1\" :xl=\"1\" style=\"min-width:100px;margin-top: 12px;\">\n                <ods-button  type=\"primary\" class=\" float-right\" @click=\"searchWizard()\">\n                    {{ $t(\"form.search\") }}</ods-button>\n\n            </ods-col>\n             <ods-divider></ods-divider>\n        </ods-row>\n    </div>\n    <!-- div table -->\n    <div v-if=\"showTable\">\n        <ods-row justify=\"center\" type=\"flex\" :gutter=\"10\">\n            <ods-col :xs=\"3\" :sm=\"3\" :md=\"3\" :lg=\"2\" :xl=\"2\" >\n                <label class=\"control-label records-title\">{{ $t(\"form.records\") }}</label>\n            </ods-col>\n            <ods-col :xs=\"5\" :sm=\"5\" :md=\"5\" :lg=\"6\" :xl=\"6\">\n\n                <ods-input type=\"string\" class=\"search-menu-title\" size=\"small\"\n                    v-model=\"searchString\">\n                     <ods-icon   class=\"input-slot-icon\" slot=\"prepend\"  name=\"search\" style=\"margin-top: 15px;\"  size=\"16\" />\n                </ods-input>\n\n\n            </ods-col>\n            <ods-col :offset=\"4\" :xs=\"12\" :sm=\"12\" :md=\"12\" :lg=\"12\" :xl=\"12\" style=\"text-align: right;\">\n                <ods-dropdown  style=\"margin-right: 10px;padding: 8px;\" @command=\"downloadData\">\n\n                <ods-dropdown-menu slot=\"dropdown\">\n                    <ods-dropdown-item v-if=\"executeSearch\" command=\"csv\" ><img  class=\"download-icons-grey\" v-bind:src=\"platformhost + \'/static/images/dashboards/icon_download.svg\'\">&nbsp;{{ $t(\"form.download.csv\") }}</ods-dropdown-item>\n                    <ods-dropdown-item v-if=\"executeSearch\" command=\"json\"  ><img  class=\"download-icons-grey\" v-bind:src=\"platformhost + \'/static/images/dashboards/icon_download.svg\'\">&nbsp;{{ $t(\"form.download.json\") }}</ods-dropdown-item>\n                    <ods-dropdown-item v-if=\"!executeSearch\" command=\"allcsv\" ><img  class=\"download-icons-grey\" v-bind:src=\"platformhost + \'/static/images/dashboards/icon_download.svg\'\">&nbsp;{{ $t(\"form.download.csv\") }}</ods-dropdown-item>\n                    <ods-dropdown-item v-if=\"!executeSearch\" command=\"alljson\"  ><img  class=\"download-icons-grey\" v-bind:src=\"platformhost + \'/static/images/dashboards/icon_download.svg\'\">&nbsp;{{ $t(\"form.download.json\") }}</ods-dropdown-item>\n                </ods-dropdown-menu>\n                </ods-dropdown>\n\n                <ods-button   class=\"primary\" @click=\"dialogOptionsColumnsVisible = true\" icon=\"ods-icon-list\"></ods-button>\n                <ods-button  class=\"primary\" icon=\"ods-icon-plus\" @click=\"dialogCreateVisible= true\"></ods-button>\n            </ods-col>\n        </ods-row>\n\n       <!--ods table-------------------->\n    <div>\n      <ods-table\n        :data=\"paginatedData\"\n        style=\"width: 100%;\"\n        :height=\"tableHeight\"\n        :stripe=\"false\"\n        :fit=\"true\"\n        :showHeader=\"true\"\n        @sort-change=\"sortChange\">\n        <ods-table-column\n          v-for=\"(column, i) in columns\"\n          :key=\"`column-${column.prop}`\"\n          :fixed=\"i === 0 && fixedFirstCol ? \'left\' : i === columns.length - 1 && fixedLastCol ? \'right\' : false\"\n          :prop=\"column.prop\"\n          :sortable=\"sortable\">\n          <template slot=\"header\" slot-scope=\"scope\">\n            {{ columns[scope.$index] !== \'\' ? columns[scope.$index].label : scope.row }}\n          </template>\n           <template slot-scope=\"scope\">\n\n        <span style=\"margin-left: 10px\">{{ scope.row[column.prop] }}</span>\n      </template>\n        </ods-table-column>\n        <ods-table-column\n            :label=\"$t(\'column.options\')\"\n            width=\"120\">\n            <template slot-scope=\"scope\">\n                 <ods-button size=\"small\" type=\"neutral\" icon=\"ods-icon-eye\" @click=\"handleShow(scope.$index, scope.row)\" style=\"margin-left:0px\">\n                </ods-button>\n                <ods-button size=\"small\" type=\"neutral\" icon=\"ods-icon-edit\" @click=\"handleEdit(scope.$index, scope.row)\" style=\"margin-left:0px\">\n                </ods-button>\n                <ods-button size=\"small\"  type=\"neutral\" @click=\"handleDelete(scope.$index, scope.row)\" style=\"margin-left:0px\"> <ods-icon    name=\"delete\"  color=\"#a73535\" />\n                </ods-button>\n            </template>\n            </ods-table-column>\n      </ods-table>\n    </div>\n    <div>\n      <ods-pagination\n        :current-page=\"page\"\n        :page-size=\"pageSize\"\n        :page-sizes=\"pageSizes\"\n        :page-count=\"pageCount\"\n        :total=\"totalItems\"\n        @current-change=\"handlePageChange\"\n        @size-change=\"handlePageSizeChange\">\n      </ods-pagination>\n    </div>\n    <!-- ods table-------------------->\n\n    </div>\n    <!-- DELETE dialog -->\n    <ods-dialog modal=\"false\" append-to-body=\"true\" :visible.sync=\"dialogDeleteVisible\" width=\"25%\">\n        <label class=\"ods-dialog-title\">{{ $t(\"message.modal.delete.title\") }}</label></br>\n        <label\n            style=\"font-size: 12px;line-height: 16px; color: #505D66;\">{{ $t(\"message.modal.delete.subtitle\") }}</label>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button type=\"primary\" class=\"float-right\" @click=\"aceptedDelete\">\n                    {{ $t(\"button.delete\") }}</ods-button>\n                <ods-button type=\"neutral\" class=\" float-right\" @click=\"dialogDeleteVisible = false\">\n                    {{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n    <!-- EDIT dialog -->\n    <ods-dialog modal=\"true\" append-to-body=\"true\" :title=\"editTitle\" :visible.sync=\"dialogEditVisible\"\n        @opened=\"openEdit\" width=\"25%\">\n        <div :class=\"[idelem, \'editor_edit_holder\']\"  ></div>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button type=\"primary\" class=\"float-right\" @click=\"aceptedEdit\">{{ $t(\"button.save\") }}\n                </ods-button>\n                <ods-button type=\"neutral\" class=\" float-right\" @click=\"dialogEditVisible = false\">\n                    {{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n    <!-- SHOW/HIDE COLUMNS dialog -->\n    <ods-dialog modal=\"false\" append-to-body=\"false\" :title=\"$t(\'form.columns\')\"\n        :visible.sync=\"dialogOptionsColumnsVisible\" width=\"25%\">\n\n        <ods-row v-for=\"visibleColumn in visibleColumns\" :key=\"visibleColumn.prop\" v-if=\"visibleColumn.label!=\'id\'\">\n            <ods-col :span=\"24\">\n                </br>\n                <el-switch v-model=\"visibleColumn.visible\" :active-text=\"visibleColumn.prop\"\n                    @change=\"dialogOptionsColumnsVisible = false;dialogOptionsColumnsVisible = true;\"></el-switch>\n            </ods-col>\n        </ods-row>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button type=\"primary\" class=\"float-right\" @click=\"aceptedChangeColumns\">\n                    {{ $t(\"button.apply\") }}</ods-button>\n                <ods-button type=\"neutral\" class=\" float-right\"\n                    @click=\"dialogOptionsColumnsVisible = false\">{{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n     <!-- DOWNLOAD dialog -->\n    <ods-dialog modal=\"false\" append-to-body=\"false\" :title=\"$t(\'message.download.all\')\"\n        :visible.sync=\"dialogDownloadVisible\" width=\"25%\">\n\n\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                  <ods-button type=\"primary\" class=\"float-right\" @click=\"aceptedDownloadOnlySelec\">\n                    {{ $t(\"button.only.selection.records\") }}</ods-button>\n                <ods-button type=\"primary\" class=\"float-right\" @click=\"aceptedDownloadAll\">\n                    {{ $t(\"button.all.records\") }}</ods-button>\n                <ods-button type=\"neutral\" class=\"float-right\"\n                    @click=\"dialogDownloadVisible = false\">{{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n    <!-- DETAIL dialog -->\n    <ods-dialog modal=\"true\" append-to-body=\"true\" :title=\"showTitle\" :visible.sync=\"dialogShowVisible\"\n        @opened=\"openShow\" width=\"25%\">\n        <div :class=\"[idelem, \'editor_show_holder\']\" ></div>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button type=\"neutral\"  class=\"float-right\" @click=\"dialogShowVisible = false\">\n                    {{ $t(\"button.close\") }}</ods-button>\n\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n    <!-- CREATE dialog -->\n    <ods-dialog modal=\"true\" append-to-body=\"true\" :title=\"$t(\'form.new.record.title\')\"\n        :visible.sync=\"dialogCreateVisible\" @opened=\"openCreate\" width=\"25%\">\n        <div :class=\"[idelem, \'editor_new_holder\']\" ></div>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button type=\"primary\"  class=\"float-right\" @click=\"aceptedCreate\">\n                    {{ $t(\"button.new\") }} <img style=\"margin-top: 6px;\" v-bind:src=\"platformhost + \'/static/images/dashboards/icon_button_plus.svg\'\">\n                </ods-button>\n                <ods-button type=\"neutral\"  class=\"float-right\" @click=\"dialogCreateVisible = false\">\n                    {{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n\n    <!-- WHERE dialog -->\n    <ods-dialog modal=\"true\" append-to-body=\"true\" :title=\"$t(\'form.where\')\" :visible.sync=\"dialogAddSelectVisible\"\n        @opened=\"opendialogAddSelect\" width=\"25%\">\n        <ods-row type=\"flex\">\n            <ods-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.select.fields\")}} <span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <ods-select size=\"small\" v-model=\"selectedParametereWhere\" :placeholder=\"$t(\'form.select.field\')\">\n                    <ods-option v-for=\"col in columnsParams\" :key=\"col.prop\" :label=\"col.label\" :value=\"col.prop\">\n                    </ods-option>\n                </ods-select>\n            </ods-col>\n        </ods-row>\n        <ods-row type=\"flex\">\n            <ods-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.operator\")}}<span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <ods-select size=\"small\" v-model=\"selectedOperatorWhere\" :placeholder=\"$t(\'form.select.operator\')\">\n                    <ods-option v-for=\"ope in operators\" :key=\"ope\" :label=\"ope\" :value=\"ope\">\n                    </ods-option>\n                </ods-select>\n            </ods-col>\n        </ods-row>\n        <ods-row type=\"flex\">\n            <ods-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.condition\")}} <span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <ods-input size=\"small\" :placeholder=\"$t(\'form.write.here\')\" v-model=\"inputValueWhere\"></ods-input>\n            </ods-col>\n        </ods-row>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button  type=\"primary\" class=\" float-right\" @click=\"aceptedAddWhereParameter\">\n                    {{ $t(\"button.apply\") }}</ods-button>\n                <ods-button  type=\"neutral\" class=\" float-right\" @click=\"dialogAddSelectVisible = false\">\n                    {{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n\n\n    <!-- ORDER BY dialog -->\n    <ods-dialog modal=\"true\" append-to-body=\"true\" title=\"Order by\" :visible.sync=\"dialogAddOrderByVisible\"\n        @opened=\"opendialogAddOrderBy\" width=\"25%\">\n        <ods-row type=\"flex\">\n            <ods-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.select.fields\")}}<span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <ods-select  v-model=\"selectedParametereOrderBy\" :placeholder=\"$t(\'form.select.field\')\">\n                    <ods-option v-for=\"col in columnsParams\" :key=\"col.prop\" :label=\"col.label\" :value=\"col.prop\">\n                    </ods-option>\n                </ods-select>\n            </ods-col>\n        </ods-row>\n        <ods-row type=\"flex\">\n            <ods-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.order.type\")}}<span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <ods-select  v-model=\"selectedOperatorOrderBy\" :placeholder=\"$t(\'form.select.operator\')\">\n                    <ods-option v-for=\"ope in orders\" :key=\"ope\" :label=\"ope\" :value=\"ope\">\n                    </ods-option>\n                </ods-select>\n            </ods-col>\n        </ods-row>\n        <ods-row class=\"ods-row-modal-grey\">\n            <ods-col>\n                </br>\n                <ods-button  type=\"primary\"  class=\"ods-self-end\" @click=\"aceptedAddOrderByParameter\">\n                    {{ $t(\"button.apply\") }}</ods-button>\n                <ods-button  type=\"neutral\"  class=\"ods-self-end\" @click=\"dialogAddOrderByVisible = false\">\n                    {{ $t(\"button.cancel\") }}</ods-button>\n            </ods-col>\n        </ods-row>\n    </ods-dialog>\n\n\n</div>\n','vm.vueconfig = {\n   el: document.getElementById(vm.id).querySelector(\'vuetemplate .appgadget\'),\n   data: {\n      typeGadget: \'withWizard\', //[\'withWizard\',\'noWizard\',\'searchOnly\']\n      hideIdColumn: false, // show or hide id column\n      initialEntity: \"\" , //variable that initializes the entity with the value assigned to it\n\n      showTable: false,\n      showSelectOntology: true,\n      showWizard: false,\n      disabledWizard: true,\n      idPath: \"\",\n      ontologies: [],\n      ontologyFieldsAndDesc: {},\n      recordSelected: \"\",\n      selectedOntology: \"\",\n      selectedOntologySchema: {},\n\n      dialogDeleteVisible: false, //hide show dialogs\n      dialogEditVisible: false,\n      dialogCreateVisible: false,\n      dialogShowVisible: false,\n      dialogOptionsColumnsVisible: false,\n      dialogAddSelectVisible: false,\n      dialogDownloadVisible:false,\n      idelem:vm.id,\n      executeSearch:false,\n      showMagnifyingGlass: true,\n      jEditor: {},\n      jShowEditor: {},\n      tableHeight: 100,\n      resizeObserver: {},\n      selectWizard: [],\n      selectWizardOptions: [],\n      orderByWizard: [],\n      orderByWizardOptions: [],\n      dialogAddOrderByVisible: false,\n      limitWizard: 100, // limit of records in the search for initialize at another value change on resetwizard too\n      offsetWizard: 0, //offset records in the search\n      whereCondition: \'\',\n      uniqueID: \'\', // save path of id\n      selectedParametereWhere: \'\',\n      selectedOperatorWhere: \'\',\n      selectedParametereOrderBy: \'\',\n      selectedOperatorOrderBy: \'\',\n      inputValueWhere: \'\',\n      editTitle: \'\',\n      showTitle: \'\',\n      downloadType:\'\',\n      visibleColumns: [], // list of visible columns\n      columnsParams: [],\n      searchString: \'\', // text for local search\n      formOptions: {\n         forms: []\n      },\n      orders: [\'ASC\', \'DESC\'],\n      operators: [\'=\', \'>\', \'<\', \'>=\', \'<=\', \'!=\'],\n      ds: [],\n      columns: [],\n      tableData: [],\n      platformhost: __env.endpointControlPanel,\n\n\n      pageSizes: [\n      10,\n      20,\n      30,\n      40,\n      50,\n      100\n      ],\n      pageSize:10,\n      minimumPageSize:10,\n      page: 1,\n      fixedFirstCol:false,\n    fixedLastCol:false,\n      sortable:true\n   },\n     computed: {\n      totalItems () {\n        return this.filteredData.length\n      },\n      pageCount () {\n        return Math.floor(this.totalItems / this.pageSize)\n      },\n      paginatedData () {\n        return this.filteredData.slice(this.pageSize * this.page - this.pageSize, this.pageSize * this.page)\n      },\n      filteredData () {\n            console.log(this.tableData.filter(this.tableDatafilter))\n        return this.tableData.filter(this.tableDatafilter)\n      },\n      pageSizes () {\n        return [\n          this.minimumPageSize,\n          this.minimumPageSize * 2,\n          this.minimumPageSize * 3,\n          this.minimumPageSize * 4,\n          this.minimumPageSize * 5,\n          this.minimumPageSize * 10\n        ]\n      },\n    },\n   methods: {\n       handlePageSizeChange (pageSize) {\n          this.pageSize = pageSize\n          this.handlePageChange(this.page)\n        },\n        handlePageChange (page) {\n          this.page = page\n        },\n      drawVueComponent: function (newData, oldData) {\n         //This will be call on new data\n      },\n      resizeEvent: function () {\n         //Resize event\n\n      },\n      destroyVueComponent: function () {\n         vm.vueapp.$destroy();\n      },\n      receiveValue: function (data) {\n         //data received from datalink\n      },\n      //function that initially reads the entities\n      loadEntities: function (search, loading) {\n         var that = this;\n         vm.getEntities().then(function (data) {\n            that.ontologies = data.data.map(function (obj) {\n               return {\n                  id: obj.id,\n                  identification: obj.identification\n               }\n            });\n\n            if(that.initialEntity!=null && that.initialEntity!==\"\"){\n               if (that.ontologies.some(e => e.identification === that.initialEntity)) {\n                     that.selectedOntology = that.initialEntity;\n                     that.onChangeEntity(that.selectedOntology);\n                     that.showSelectOntology = true;\n                     return;\n                  } else {\n                     that.$notify({\n                        message: that.$t(\'error.message.ontology\'),\n                        type: \'error\'\n                     });\n                  }\n            }\n            var urlparam = urlParamService.generateFiltersForGadgetId(vm.id);\n            if (typeof urlparam !== \'undefined\' && urlparam !== null && urlparam.length > 0) {\n               if (urlparam[0].exp != null) {\n                  var urlontology = urlparam[0].exp.replace(/\"/g, \'\');\n                  if (that.ontologies.some(e => e.identification === urlontology)) {\n                     that.selectedOntology = urlontology;\n                     that.onChangeEntity(that.selectedOntology);\n                     that.showSelectOntology = true;\n                     return;\n                  } else {\n                     that.$notify({\n                        message: that.$t(\'error.message.ontology\'),\n                        type: \'error\'\n                     });\n                  }\n               }\n            } else {\n               that.showSelectOntology = false;\n            }\n\n         })\n      },\n      //function that obtains the information of the selected ontology\n      loadHeadTable: function () {\n         var that = this;\n         if (this.ontologies != null && this.ontologies.length > 0) {\n            for (var i = 0; i < this.ontologies.length; i++) {\n               if (this.ontologies[i].identification === this.selectedOntology) {\n                  vm.crudGetEntityInfo(this.ontologies[i].id).then(function (data) {\n                     that.uniqueID = data.data.uniqueId;\n                     that.selectedOntologySchema = that.changeDescriptionForTitle(data.data.jsonSchema);\n                  });\n                  break;\n               }\n            }\n         }\n         vm.getOntologyFieldsAndDesc(this.selectedOntology).then(function (data) {\n            that.ontologyFieldsAndDesc = data.data;\n            that.loadData();\n         })\n      },\n      //function that gets the data and loads it to be displayed in the table\n      //difference if it is an initial query or the search button is pressed\n      loadData: function (fromSearch) {\n         var that = this;\n         that.showTable = false;\n         var selectStatement = {};\n         if (typeof fromSearch == \'undefined\' || fromSearch == null || fromSearch == false) {\n            selectStatement = {\n               ontology: this.selectedOntology,\n               columns: [],\n               where: [],\n               orderBy: [],\n               limit: this.limitWizard,\n               offset: this.offsetWizard\n            };\n         } else {\n            selectStatement = {\n               ontology: this.selectedOntology,\n               columns: [],\n               where: this.mapArrayToObjects(this.selectWizard),\n               orderBy: this.mapArrayToObjects(this.orderByWizard),\n               limit: this.limitWizard,\n               offset: this.offsetWizard\n            };\n         }\n         vm.crudQueryParams(selectStatement).then(function (data) {\n            that.showTable = true;\n            that.disabledWizard = false;\n            //create columns from that.ontologyFieldsAndDesc\n            var keys = Object.keys(that.ontologyFieldsAndDesc);\n\n            //validate error from data\n            if (typeof data.data.error !== \'undefined\') {\n               that.$notify({\n                  message: that.$t(\'error.message.querying.the.data\'),\n                  type: \'error\'\n               });\n               return {};\n            }\n            if (keys != null && keys.length > 0) {\n               if (typeof fromSearch != \'undefined\' && fromSearch != null && fromSearch) {\n                  var index = that.columns.findIndex(function (elem) {\n                     return elem.prop === that.uniqueID\n                  });\n                  if (index < 0) {\n                     that.idPath = that.uniqueID;\n                     that.columns.push({\n                        prop: that.uniqueID,\n                        label: \"id\"\n                     });\n\n                  }\n                  that.tableData = data.data.map(function (dat) {\n                     var refinedData = {};\n                     for (var i = 0; i < that.columns.length; i++) {\n                        let path = that.columns[i].prop.split(\'.\');\n                           try {\n                                  refinedData[that.columns[i].prop] = path.reduce((a, v) => a[v], dat);              \n                              } catch (error) {\n                                   refinedData[that.columns[i].prop] = null; \n                              }                     }\n\n                     return refinedData;\n                  })\n               } else {\n                  that.columns = [];\n\n                  var index = keys.findIndex(function (elem) {\n                     return elem === that.uniqueID\n                  });\n                  if (index > -1) {\n                     keys.splice(index, 1);\n                  }\n                  that.idPath = that.uniqueID;\n                  that.columns.push({\n                     prop: that.uniqueID,\n                     label: \"id\"\n                  });\n                  keys = keys.sort(that.orderKeys);\n                  //initial construction of table columns\n                  for (var i = 0; i < keys.length; i++) {\n                     var description = that.ontologyFieldsAndDesc[keys[i]].description;\n                     if (description == null || typeof description == undefined || description.length == 0) {\n                        description = that.ontologyFieldsAndDesc[keys[i]].path;\n                     }\n                     description = that.$t(description) || description;\n                     that.columns.push({\n                        prop: that.ontologyFieldsAndDesc[keys[i]].path,\n                        thetype: that.ontologyFieldsAndDesc[keys[i]].type,\n                        label: description,\n                        minWidth: 100,\n                        sortable: \'custom\'\n                     });\n\n                  }\n\n                  //mapping the data to display\n                  that.tableData = data.data.map(function (dat) {\n                     var refinedData = {};\n                     for (var i = 0; i < that.columns.length; i++) {\n                        if(typeof that.columns[i].prop!=\'undefined\' && that.columns[i].prop!=null){\n                           let path = that.columns[i].prop.split(\'.\');\n                              try {\n                                  refinedData[that.columns[i].prop] = path.reduce((a, v) => a[v], dat);              \n                              } catch (error) {\n                                   refinedData[that.columns[i].prop] = null; \n                              }                        }\n                     }\n\n                     return refinedData;\n                  })\n                  console.log(that.tableData.filter(that.tableDatafilter))\n               }\n               //hide or show id columns\n               if (that.hideIdColumn) {\n\n                  var index = that.columns.findIndex(function (elem) {\n                     return elem.label === \'id\'\n                  });\n                  if (index > -1) {\n                     that.columns.splice(index, 1);\n                  }\n\n               }\n               if (that.visibleColumns.length == 0 && that.columns.length > 0) {\n                  that.visibleColumns = Array.from(that.columns);\n                  that.columnsParams = Array.from(that.columns);\n                  that.visibleColumns.forEach(function (element) {\n                     element.visible = true;\n                  });\n               }\n\n\n            }\n         })\n      },\n      //function that is executed when the edition of a record is opened\n      openEdit: function () {\n         var that = this;\n         vm.crudFindById(this.recordSelected, this.selectedOntology).then(function (data) {\n            delete data.data[0]._id;\n            delete data.data[0].contextData;\n            if (typeof that.jEditor.destroy == \'function\') that.jEditor.destroy();\n            that.jEditor = new JSONEditor(document.getElementsByClassName(vm.id+\' editor_edit_holder\')[0], {\n               schema: JSON.parse(that.selectedOntologySchema),\n               startval: data.data[0],\n               theme: \'bootstrap3\',\n               iconlib: \'fontawesome4\',\n               disable_properties: true,\n               disable_edit_json: true,\n               disable_collapse: true,\n               disable_array_reorder: true,\n               disable_array_delete_all_rows: true,\n               disable_array_delete_last_row: true,\n               show_errors: \'change\'\n            });\n         })\n      },\n      //function that is executed when the detail of a record is opened\n      openShow: function () {\n         var that = this;\n         vm.crudFindById(this.recordSelected, this.selectedOntology).then(function (data) {\n            delete data.data[0]._id;\n            delete data.data[0].contextData;\n            if (typeof that.jShowEditor.destroy == \'function\') that.jShowEditor.destroy();\n            that.jShowEditor = new JSONEditor(document.getElementsByClassName(vm.id+\' editor_show_holder\')[0], {\n               schema: JSON.parse(that.selectedOntologySchema),\n               startval: data.data[0],\n               theme: \'bootstrap3\',\n               mode: \'view\',\n               iconlib: \'fontawesome4\',\n               disable_properties: true,\n               disable_edit_json: true,\n               disable_collapse: true,\n               disable_array_reorder: true,\n               disable_array_delete_all_rows: true,\n               disable_array_delete_last_row: true,\n               show_errors: \'change\'\n            });\n            that.jShowEditor.disable();\n         })\n      },\n      //function that is executed when modal of creating a record is opened\n      openCreate: function () {\n         var that = this;\n         vm.crudFindById(this.recordSelected, this.selectedOntology).then(function (data) {\n\n            if (typeof that.jEditor.destroy == \'function\') that.jEditor.destroy();\n            that.jEditor = new JSONEditor(document.getElementsByClassName(vm.id+\' editor_new_holder\')[0], {\n               schema: JSON.parse(that.selectedOntologySchema),\n               startval: undefined,\n               theme: \'bootstrap3\',\n               iconlib: \'fontawesome4\',\n               disable_properties: true,\n               disable_edit_json: true,\n               disable_collapse: true,\n               disable_array_reorder: true,\n               disable_array_delete_all_rows: true,\n               disable_array_delete_last_row: true,\n               show_errors: \'change\'\n            });\n         })\n\n\n      },\n      //function that is executed when accepting a visibility change in the columns\n      aceptedChangeColumns: function () {\n            //delete columns visible = false\n            //add columns visible = true if not exist\n\n            var that = this;\n            this.visibleColumns.forEach(function (visibleCol) {\n               if (that.columns.length > 0) {\n                  var find = false;\n                  for (var i = 0; i < that.columns.length; i++) {\n                     if (that.columns[i].prop == visibleCol.prop) {\n                        find = true;\n                        if (!visibleCol.visible) {\n                           that.columns.splice(i, 1);\n                        }\n                        break;\n                     }\n                  }\n                  if (!find && visibleCol.visible) {\n                     var obj = Object.assign({}, visibleCol);\n                     delete obj.visible;\n                     that.columns.push(obj);\n                  }\n               } else {\n                  if (visibleCol.visible) {\n                     var obj = Object.assign({}, visibleCol);\n                     delete obj.visible;\n                     that.columns.push(obj);\n                  }\n               }\n            });\n            this.dialogOptionsColumnsVisible = false;\n            this.loadData(true);\n         }\n\n         ,\n      //function that is executed when clicking on edit a record\n      handleEdit: function (index, row) {\n         this.recordSelected = row[this.idPath];\n         this.editTitle = this.$t(\'form.edit.record\') + this.recordSelected;\n         this.dialogEditVisible = true;\n\n      },\n      //function that is executed when clicking on show a record\n      handleShow: function (index, row) {\n         this.recordSelected = row[this.idPath];\n         this.showTitle = this.$t(\'form.detail.record\') + this.recordSelected;\n         this.dialogShowVisible = true;\n\n      },\n      //function that is executed when clicking on delete a record\n      handleDelete: function (index, row) {\n         this.recordSelected = row[this.idPath];\n         this.dialogDeleteVisible = true;\n      },\n      //function that is executed when accepting to edit a record\n      aceptedEdit: function () {\n         var that = this;\n         console.log(this.jEditor.getValue());\n         vm.crudUpdate(this.jEditor.getValue(), this.selectedOntology, this.recordSelected).then(function (data) {\n            that.dialogEditVisible = fal