ectedOperatorOrderBy != \'undefined\' && this.selectedOperatorOrderBy != null &&\n            typeof this.selectedParametereOrderBy != \'undefined\' && this.selectedParametereOrderBy != null) {\n            var paramDescription = \'\';\n            var type = \'\';\n            for (var i = 0; i < this.columnsParams.length; i++) {\n               if (this.columnsParams[i].prop == this.selectedParametereOrderBy) {\n                  paramDescription = this.columnsParams[i].label;\n                  break\n               }\n            }\n            var resultDescription = paramDescription + \" \" + this.selectedOperatorOrderBy;\n            var resultPath = {\n               column: this.selectedParametereOrderBy,\n               order: this.selectedOperatorOrderBy\n            };\n            this.orderByWizardOptions.push({\n               label: resultDescription,\n               value: JSON.stringify(resultPath)\n            });\n\n            this.dialogAddOrderByVisible = false;\n         }\n      },\n      //initialize orderby\n      dialogAddOrderByVisibleFunction: function () {\n         this.selectedOperatorOrderBy = null;\n         this.selectedParametereOrderBy = null;\n         this.dialogAddOrderByVisible = true;\n      },\n      //initialize where\n      dialogAddSelectVisibleFunction: function () {\n         this.selectedParametereWhere = null;\n         this.selectedOperatorWhere = null;\n         this.inputValueWhere = \"\";\n         this.dialogAddSelectVisible = true;\n      },\n      orderColumns: function (a, b) {\n         if (a.label == \'id\') {\n            return 1;\n         } else if (b.label == \'id\') {\n            return -1;\n         } else if (a.label > b.label) {\n            return 1;\n         } else if (a.label < b.label) {\n            return -1;\n         }\n         return 0;\n      },\n      orderKeys: function (a, b) {\n         if (a == \'id\') {\n            return 1;\n         } else if (b == \'id\') {\n            return -1;\n         } else if (a > b) {\n            return 1;\n         } else if (a < b) {\n            return -1;\n         }\n         return 0;\n      },\n\n      tableDatafilter: function (element) {\n         if (this.searchString == null || this.searchString.trim().length == 0) {\n            return true;\n         }\n         return JSON.stringify(element).toLowerCase().indexOf(this.searchString.toLowerCase()) > -1;\n\n      },\n      aceptedDownloadAll: function(){\n         var that = this;\n         vm.validationDownloadEntity(this.selectedOntology,this.downloadType).then(function(data){\n            if(data.data.message==\'ok\'){\n               if(that.downloadType==\'csv\'){\n                  vm.downloadEntityAllCsv(that.selectedOntology);\n                  that.dialogDownloadVisible=false;\n               }else{\n                  vm.downloadEntityAllJson(that.selectedOntology);\n                  that.dialogDownloadVisible=false;\n               }\n            }else{\n                that.$notify({\n                        message: that.$t(data.data.message),\n                        type: \'error\'\n                     });\n            }\n         })\n      },\n      aceptedDownloadOnlySelec: function () {\n         var selection = encodeURIComponent(JSON.stringify({ ontology: this.selectedOntology, columns: [], where: this.mapArrayToObjects(this.selectWizard), orderBy: this.mapArrayToObjects(this.orderByWizard), limit: this.limitWizard, offset: this.offsetWizard }));\n         var that = this;\n         vm.validationDownloadEntitySelected(this.selectedOntology, selection,this.downloadType).then(function (data) {\n            if (data.data.message == \'ok\') {\n               if (that.downloadType == \'csv\') {\n                  vm.downloadEntitySelectedCsv(that.selectedOntology, selection);\n                  that.dialogDownloadVisible = false;\n               } else {\n                  vm.downloadEntitySelectedJson(that.selectedOntology, select