¾:\'£ØñË€ÿDtÔçÂÜ*Wis_½½Ë>\0 ñÃ³…Bq/8´žö\nfdÍG¾/H\0»wºWƒÙž€C“–¨ 7|J¶i\0/Ò¾¿Â¹\rêª›.½¸?ê×‰°¯Ã•¬ŠÛgïk÷“¾\0Páœh’}ŒPue*]Wäf­hšE	 ÁmF1ñ]œ‰íY9äúzà=©ÍÖžSÚP•¿³DI¤Íw\\iù¦´	:òÈp¶ùÂ/=…qÙeáÌiˆz$›ID)o´ØãpI!õWÝ‰’¬Xf¢\\)2‡æÆ«cBÑ|óB\0Z–ïòÇ½;;ö@–$QŽä¶ÔËÚfÏ…ÅýÝË;º;n€ÝügÖFñÕ¨Pà®v›rž}&W7ájN|ç¥½ék)ü/š:Iù.ã¿¬ÇÉ5Žæ‘[xŽ¾mký­7ã\ZS wl?gt7{t—›é¿ï:O¥nÔÞÏ5f½×8šïžëÔ†ôG÷Þ»ƒ£Ù{ïSGmË(',1,'<!--Focus here and F11 or F10 to full screen editor-->\n<!-- Write your CSS <style></style> here -->\n<div class=\"gadget-app\">\n    <ods-date-picker v-if=\"type !== \'quarter\'\"\n        v-model=\"value\"\n        :type=\"type\"\n        range-separator=\"To\"\n        placeholder=\"\"\n        start-placeholder=\"\"\n        end-placeholder=\"\"\n        range-separator=\"\"\n        @change=\"handleChange\"\n        :picker-options=\"datepickerOptions\"\n    >\n    </ods-date-picker>\n        <ods-select v-if=\"type === \'quarter\'\"\n        v-model=\"value\"\n        placeholder=\"Pick Quarter\"\n        :clearable=\"true\"\n        :multiple=\"false\"\n        @change=\"handleChange\"\n        >\n        <ods-option\n            v-for=\"item in qdates\"\n            :key=\"item.value\"\n            :label=\"item.text\"\n            :value=\"item.value\"\n            >\n        </ods-option>\n    </ods-select>\n</div>','//Write your Vue with ODS JSON controller code here\n\n//Focus here and F11 or F10 to full screen editor\n\n//This function will be call once to init components\n\nvm.vueconfig = {\n	el: document.getElementById(vm.id).querySelector(\'vuetemplate  .gadget-app\'),\n	data: {\n		ds: [],\n		value: \"\",\n		placeholder: vm.tparams.parameters.placeholder,\n		type: vm.tparams.parameters.type,\n		datepickerOptions: {\n			disabledDate: function disabledDate(time) {\n				var d = new Date()\n				d.setYear(d.getFullYear() - parseInt(vm.tparams.parameters.firstPickDate))\n				return (vm.tparams.parameters.lastPickDateToday && time.getTime() > Date.now()) || time.getTime() < d.getTime()\n			}\n		}\n	},\n	computed: {\n		qdates () {\n			if (this.type === \'quarter\') {\n				var d = new Date()\n				d.setYear(d.getFullYear() - parseInt(vm.tparams.parameters.firstPickDate))\n				d.setMonth(d.getMonth()+3)\n				var now = new Date()\n				var startQs = [0,3,6,9]\n				var month = d.getMonth()\n				var firstQ = startQs.filter(function(q){\n					return month >= q\n				})\n				firstQ =  firstQ[firstQ.length-1]\n				var options = []\n				for (var year = d.getFullYear();year <= now.getFullYear();year++) {\n					for (var quarter = (year === d.getFullYear()?firstQ:0);quarter <= (now.getFullYear()===year?firstQ:11);quarter+=3) {\n						var stepDate = new Date()\n						stepDate.setYear(year)\n						stepDate.setMonth(quarter)\n						options.push({\n							value: this.formatDate(stepDate, vm.tparams.parameters.filterformat),\n							text: \"Q\" + (startQs.indexOf(quarter)+1) + \"-\" + year\n						})\n					}\n				}\n				return options\n			} else {\n				return  []\n			}\n		}\n	},\n	methods: {\n		drawVueComponent: function (newData, oldData) {\n			//This will be call on new data\n		},\n		resizeEvent: function () {\n			//Resize event\n		},\n		destroyVueComponent: function () {\n			vm.vueapp.$destroy();\n		},\n		receiveValue: function (data) {\n			//data received from datalink\n		},\n		sendValue: vm.sendValue,\n		sendFilter: vm.sendFilter,\n		handleChange: function (e) {\n			if (vm.tparams.parameters.type == \"daterange\" || vm.tparams.parameters.filtertype == \"daterange\") {\n				var initdate, enddate;\n				if (e == null || e === \"\") {\n					vm.sendFilter(\"date\", null, \"between\")\n				} else {\n					switch (vm.tparams.parameters.type) {\n						case \"daterange\":\n							initdate = this.formatDate(e[0], vm.tparams.parameters.filterformat)\n							enddate = this.formatDate(e[1], vm.tparams.parameters.filterformat)\n							break;\n						case \"year\":\n							initdate = this.formatDate(e, vm.tparams.parameters.filterformat)\n							//end date will be last day of year\n							enddate = this.formatDate(new Date(e.getFullYear() + 1, 0, 0), vm.tparams.parameters.filterformat)\n							break;\n						case \"month\":\n							initdate = this.formatDate(e, vm.tparams.parameters.filterformat)\n							enddate = this.formatDate(new Date(e.getFullYear(), e.getMonth() + 1, 0), vm.tparams.parameters.filterformat)\n							break;\n						case \"quarter\":\n							e = new Date(e)\n							initdate = this.formatDate(new Date(e.getFullYear(), e.getMonth() , 1), vm.tparams.parameters.filterformat)\n							enddate = this.formatDate(new Date(e.getFullYear(), e.getMonth() + 3, 0), vm.tparams.parameters.filterformat)\n							break;\n					}\n					vm.sendFilter(\"date\", \"\'\" + initdate + \"\' and \'\" + enddate + \"\'\", \"between\")\n				}\n			} else {\n				if (this.type !== \'quarter\') {\n					if (e == null) {\n						vm.sendFilter(\"date\", null)\n					} else {\n						vm.sendFilter(\"date\", \"\'\" + this.formatDate(e, vm.tparams.parameters.filterformat) + \"\'\")\n					}\n				} else {\n					vm.sendFilter(\"date\", \"\'\" + initdate + \"\' and \'\" + enddate + \"\'\", \"between\")\n				}\n			}\n\n		},\n		formatDate: function (date, format) {\n			switch (format) {\n				case \"YYYY-MM-DDTHH:mm:ss.sssZ\":\n					return date.toISOString()\n				case \"YYYY-MM-DD\":\n					var day = date.getDate();\n					var month = date.getMonth() + 1;\n					var year = date.getFullYear();\n					if (day < 10) {\n						day = \'0\' + day;\n					}\n					if (month < 10) {\n						month = \'0\' + month;\n					}\n					return year + \"-\" + month + \"-\" + day\n				case \"YYYY-MM\":\n					var month = date.getMonth() + 1;\n					var year = date.getFullYear();\n					if (month < 10) {\n						month = \'0\' + month;\n					}\n					return year + \"-\" + month\n				case \"YYYY\":\n					var year = date.getFullYear();\n					return year + \"\"\n			}\n		}\n	}\n}\n\n//Init Vue app\nvm.vueapp = new Vue(vm.vueconfig);\n','vueJS','2026-07-05 18:39:22','administrator'),('MASTER-GadgetTemplate-19','{\n	\"gform\": [\n		{\n			\"id\": 1,\n			\"type\": \"input-text\",\n			\"name\": \"title\",\n			\"default\": \"\",\n			\"title\": \"Title\"\n		},\n		{\n			\"id\": 1,\n			\"type\": \"input-text\",\n			\"name\": \"postText\",\n			\"default\": \"\",\n			\"title\": \"Text Add to end of value\"\n		},\n		{\n			\"id\": 6,\n			\"type\": \"ds-field\",\n			\"name\": \"valueField\",\n			\"title\": \"Real Value\"\n		},\n		{\n			\"id\": 4,\n			\"type\": \"checkbox\",\n			\"name\": \"showObj\",\n			\"default\": true\n		},\n		{\n			\"id\": 1,\n			\"type\": \"input-text\",\n			\"name\": \"objText\",\n			\"default\": \"Objetive:\",\n			\"title\": \"Objetive Text\"\n		},\n		{\n			\"id\": 6,\n			\"type\": \"ds-field\",\n			\"name\": \"objField\"\n		},\n		{\n			\"id\": 5,\n			\"type\": \"color-picker\",\n			\"name\": \"colorLessObj\",\n			\"default\": \"rgba(174, 5, 5, 1)\",\n			\"title\": \"Color for less than objetive\"\n		},\n		{\n			\"id\": 5,\n			\"type\": \"color-picker\",\n			\"name\": \"colorEqualObj\",\n			\"default\": \"rgba(255, 140, 0, 1)\",\n			\"title\": \"Color for equal than objetive\"\n		},\n		{\n			\"id\": 5,\n			\"type\": \"color-picker\",\n			\"name\": \"colorMoreObj\",\n			\"default\": \"rgba(0, 149, 0, 1)\",\n			\"title\": \"Color for more than objetive\"\n		},\n		{\n			\"id\": 3,\n			\"type\": \"selector\",\n			\"name\": \"alignH\",\n			\"options\": [\n				{\n					\"value\": \"left\",\n					\"text\": \"\"\n				},\n				{\n					\"value\": \"right\",\n					\"text\": \"\"\n				},\n				{\n					\"value\": \"center\",\n					\"text\": \"\"\n				}\n			],\n			\"title\": \"Position Horizontal\",\n			\"default\": \"center\"\n		},\n		{\n			\"id\": 3,\n			\"type\": \"selector\",\n			\"name\": \"alignV\",\n			\"options\": [\n				{\n					\"value\": \"center\",\n					\"text\": \"\"\n				},\n				{\n					\"value\": \"start\",\n					\"text\": \"top\"\n				},\n				{\n					\"value\": \"end\",\n					\"text\": \"bottom\"\n				}\n			],\n			\"title\": \"Position Vertical\",\n			\"default\": \"center\"\n		},\n		{\n			\"id\": 3,\n			\"type\": \"selector\",\n			\"name\": \"textAlign\",\n			\"options\": [\n				{\n					\"value\": \"center\",\n					\"text\": \"\"\n				},\n				{\n					\"value\": \"right\",\n					\"text\": \"\"\n				},\n				{\n					\"value\": \"left\",\n					\"text\": \"\"\n				}\n			],\n			\"title\": \"Text Align\",\n			\"default\": \"left\"\n		},\n		{\n			\"id\": 4,\n			\"type\": \"checkbox\",\n			\"name\": \"swapColor\",\n			\"default\": false,\n			\"title\": \"Swap Colors \"\n		}\n	]\n}','2026-07-05 18:39:22','Simple value gadget for objetives with color config','','KPI_Obj',NULL,1,'<!--Focus here and F11 or F10 to full screen editor-->\n<!-- Write your CSS <style></style> here -->\n<style>\n    .fullsize {\n		height: 100%;\n		width: 100%;\n		display: flex\n	}\n	h2 {\n		font-size: 50px !important;\n		padding: 5px !important;\n		font-weight: bold\n	}\n	i {\n	  font-style: italic;\n	}\n	h3 {\n		font-size: 35px !important;\n		padding: 3px !important;\n	}\n	h4 {\n		font-size: 20px !important;\n		padding: 2px !important;\n		color: #aaaaaa\n	}\n</style>\n<div class=\"gadget-app fullsize\" :style=\"{\'text-align\': textAlign, \'justify-content\': alignH, \'align-items\': alignV}\">\n	<div>\n		<h2 :style=\"{\'color\': color }\">{{real + postText}}</h2>\n		<h3><i>{{title}}</i></h3>\n		<h4 v-if=\"showObj\">{{objText + \' \' + obj + postText}}</h4>\n	</div>\n</div>','//Write your Vue JSON controller code here\n\n//Focus here and F11 to full screen editor\n\n//This function will be call once to init components\n\nvm.vueconfig = {\n	el: document.getElementById(vm.id).querySelector(\'vuetemplate  .gadget-app\'),\n	data:{\n		ds:[],\n		title: vm.tparams.parameters.title,\n		objText: vm.tparams.parameters.objText,\n		showObj: vm.tparams.parameters.showObj,\n		postText: vm.tparams.parameters.postText,\n		alignH: vm.tparams.parameters.alignH,\n		alignV: vm.tparams.parameters.alignV,\n		textAlign: vm.tparams.parameters.textAlign\n	},\n	computed: {\n		real() {\n			if (this.ds.length == 0) {\n				return \"\";\n			} else {\n				return vm.utils.findValues(this.ds[0], vm.tparams.parameters.valueField)\n			}\n		},\n		color() {\n			if (this.obj == this.real) {\n				return vm.tparams.parameters.colorEqualObj\n			} else if ((this.obj > this.real && !vm.tparams.parameters.swapColor) || (this.obj < this.real && vm.tparams.parameters.swapColor)) {\n				return vm.tparams.parameters.colorLessObj\n			} else {\n				return vm.tparams.parameters.colorMoreObj\n			}\n		},\n		obj() {\n			if (this.ds.length == 0) {\n				return \"\";\n			} else {\n				return vm.utils.findValues(this.ds[0], vm.tparams.parameters.objField)\n			}\n		}\n	},\n	methods:{\n		drawVueComponent: function(newData,oldData){\n			//This will be call on new data\n		},\n		resizeEvent: function(){\n			//Resize event\n		},\n		destroyVueComponent: function(){\n			vm.vueapp.$destroy();\n		},\n		receiveValue: function(data){\n			//data received from datalink\n		},\n		sendValue: vm.sendValue,\n		sendFilter: vm.sendFilter\n	}\n}\n\n//Init Vue app\nvm.vueapp = new Vue(vm.vueconfig);\n','vueJS','2026-07-05 18:39:22','administrator'),('MASTER-GadgetTemplate-20','{\n	\"metainf\": {\n		\"category\": \"Predefined\",\n		\"order\": -95\n	},\n	\"gform\": [\n		{\n			\"id\": 8,\n			\"type\": \"section\",\n			\"elements\": [\n				{\n					\"id\": 2,\n					\"type\": \"input-number\",\n					\"name\": \"center_latitude\",\n					\"default\": \"0\",\n					\"title\": \"Latitude\"\n				},\n				{\n					\"id\": 2,\n					\"type\": \"input-number\",\n					\"name\": \"center_longitude\",\n					\"default\": \"0\",\n					\"title\": \"Longitude\"\n				},\n				{\n					\"id\": 2,\n					\"type\": \"input-number\",\n					\"name\": \"center_zoom\",\n					\"default\": \"0\",\n					\"title\": \"Zoom\",\n					\"min\": \"1\",\n					\"max\": \"20\"\n				}\n			],\n			\"name\": \"center\",\n			\"title\": \"Center\"\n		},\n		{\n			\"id\": 8,\n			\"type\": \"section\",\n			\"elements\": [\n				{\n			