ons-columns\"\n                    @click=\"dialogOptionsColumnsVisible = true\"><img\n                        v-bind:src=\"platformhost + \'/static/images/dashboards/icon_options_dots_bars.svg\'\"></el-button>\n                <el-button size=\"small\" class=\"button-plus-create\" @click=\"dialogCreateVisible= true\"><img\n                        v-bind:src=\"platformhost + \'/static/images/dashboards/icon_button_plus.svg\'\"></el-button>\n            </el-col>\n        </el-row>\n\n        <!--el-search-table-pagination  -->\n        <el-search-table-pagination type=\"local\" :height=\"tableHeight\" @sort-change=\"sortChange\"\n            :data=\"tableData.filter(tableDatafilter)\" :page-sizes=\"[10, 25, 50]\" :columns=\"columns\"\n            :form-options=\"formOptions\">\n            <el-table-column :label=\"$t(\'column.options\')\" slot=\"append\" width=\"120px\">\n                <template slot-scope=\"scope\">\n                    <el-button size=\"mini\" type=\"text\" @click=\"handleShow(scope.$index, scope.row)\"><img\n                            v-bind:src=\"platformhost + \'/static/images/dashboards/icon_eye.svg\'\">\n                    </el-button>\n                    <el-button size=\"mini\" type=\"text\" @click=\"handleEdit(scope.$index, scope.row)\"><img\n                            v-bind:src=\"platformhost + \'/static/images/dashboards/edit.svg\'\" class=\"edit-icon-blue\">\n                    </el-button>\n                    <el-button size=\"mini\" type=\"text\" @click=\"handleDelete(scope.$index, scope.row)\"><img\n                            v-bind:src=\"platformhost + \'/static/images/dashboards/delete.svg\'\" class=\"trash-icon-red\">\n                    </el-button>\n                </template>\n            </el-table-column>\n        </el-search-table-pagination>\n    </div>\n    <!-- DELETE dialog -->\n    <el-dialog modal=\"false\" append-to-body=\"true\" :visible.sync=\"dialogDeleteVisible\" width=\"25%\">\n        <label class=\"el-dialog-title\">{{ $t(\"message.modal.delete.title\") }}</label></br>\n        <label\n            style=\"font-size: 12px;line-height: 16px; color: #505D66;\">{{ $t(\"message.modal.delete.subtitle\") }}</label>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedDelete\">\n                    {{ $t(\"button.delete\") }}</el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\" @click=\"dialogDeleteVisible = false\">\n                    {{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n    <!-- EDIT dialog -->\n    <el-dialog modal=\"true\" append-to-body=\"true\" :title=\"editTitle\" :visible.sync=\"dialogEditVisible\"\n        @opened=\"openEdit\" width=\"25%\">\n        <div :class=\"[idelem, \'editor_edit_holder\']\" ></div>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedEdit\">{{ $t(\"button.save\") }}\n                </el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\" @click=\"dialogEditVisible = false\">\n                    {{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n    <!-- SHOW/HIDE COLUMNS dialog -->\n    <el-dialog modal=\"false\" append-to-body=\"false\" :title=\"$t(\'form.columns\')\"\n        :visible.sync=\"dialogOptionsColumnsVisible\" width=\"25%\">\n\n        <el-row v-for=\"visibleColumn in visibleColumns\" :key=\"visibleColumn.prop\" v-if=\"visibleColumn.label!=\'id\'\">\n            <el-col :span=\"24\">\n                </br>\n                <el-switch v-model=\"visibleColumn.visible\" :active-text=\"visibleColumn.prop\"\n                    @change=\"dialogOptionsColumnsVisible = false;dialogOptionsColumnsVisible = true;\"></el-switch>\n            </el-col>\n        </el-row>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedChangeColumns\">\n                    {{ $t(\"button.apply\") }}</el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\"\n                    @click=\"dialogOptionsColumnsVisible = false\">{{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n     <!-- DOWNLOAD dialog -->\n    <el-dialog modal=\"false\" append-to-body=\"false\" :title=\"$t(\'message.download.all\')\"\n        :visible.sync=\"dialogDownloadVisible\" width=\"25%\">\n\n\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                  <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedDownloadOnlySelec\">\n                    {{ $t(\"button.only.selection.records\") }}</el-button>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedDownloadAll\">\n                    {{ $t(\"button.all.records\") }}</el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\"\n                    @click=\"dialogDownloadVisible = false\">{{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n    <!-- DETAIL dialog -->\n    <el-dialog modal=\"true\" append-to-body=\"true\" :title=\"showTitle\" :visible.sync=\"dialogShowVisible\"\n        @opened=\"openShow\" width=\"25%\">\n        <div :class=\"[idelem, \'editor_show_holder\']\" ></div>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"dialogShowVisible = false\">\n                    {{ $t(\"button.close\") }}</el-button>\n\n            </el-col>\n        </el-row>\n    </el-dialog>\n    <!-- CREATE dialog -->\n    <el-dialog modal=\"true\" append-to-body=\"true\" :title=\"$t(\'form.new.record.title\')\"\n        :visible.sync=\"dialogCreateVisible\" @opened=\"openCreate\" width=\"25%\">\n        <div :class=\"[idelem, \'editor_new_holder\']\" ></div>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedCreate\">\n                    {{ $t(\"button.new\") }} <img style=\"margin-top: 6px;\" v-bind:src=\"platformhost + \'/static/images/dashboards/icon_button_plus.svg\'\">\n                </el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\" @click=\"dialogCreateVisible = false\">\n                    {{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n\n    <!-- WHERE dialog -->\n    <el-dialog modal=\"true\" append-to-body=\"true\" :title=\"$t(\'form.where\')\" :visible.sync=\"dialogAddSelectVisible\"\n        @opened=\"opendialogAddSelect\" width=\"25%\">\n        <el-row type=\"flex\">\n            <el-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.select.fields\")}} <span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <el-select size=\"small\" v-model=\"selectedParametereWhere\" :placeholder=\"$t(\'form.select.field\')\">\n                    <el-option v-for=\"col in columnsParams\" :key=\"col.prop\" :label=\"col.label\" :value=\"col.prop\">\n                    </el-option>\n                </el-select>\n            </el-col>\n        </el-row>\n        <el-row type=\"flex\">\n            <el-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.operator\")}}<span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <el-select size=\"small\" v-model=\"selectedOperatorWhere\" :placeholder=\"$t(\'form.select.operator\')\">\n                    <el-option v-for=\"ope in operators\" :key=\"ope\" :label=\"ope\" :value=\"ope\">\n                    </el-option>\n                </el-select>\n            </el-col>\n        </el-row>\n        <el-row type=\"flex\">\n            <el-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.condition\")}} <span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <el-input size=\"small\" :placeholder=\"$t(\'form.write.here\')\" v-model=\"inputValueWhere\"></el-input>\n            </el-col>\n        </el-row>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedAddWhereParameter\">\n                    {{ $t(\"button.apply\") }}</el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\" @click=\"dialogAddSelectVisible = false\">\n                    {{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n\n\n    <!-- ORDER BY dialog -->\n    <el-dialog modal=\"true\" append-to-body=\"true\" title=\"Order by\" :visible.sync=\"dialogAddOrderByVisible\"\n        @opened=\"opendialogAddOrderBy\" width=\"25%\">\n        <el-row type=\"flex\">\n            <el-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.select.fields\")}}<span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <el-select size=\"small\" v-model=\"selectedParametereOrderBy\" :placeholder=\"$t(\'form.select.field\')\">\n                    <el-option v-for=\"col in columnsParams\" :key=\"col.prop\" :label=\"col.label\" :value=\"col.prop\">\n                    </el-option>\n                </el-select>\n            </el-col>\n        </el-row>\n        <el-row type=\"flex\">\n            <el-col :span=\"24\">\n                <label class=\"control-label\">{{$t(\"form.order.type\")}}<span class=\"required\" aria-required=\"true\">\n                        *</span></label></br>\n                <el-select size=\"small\" v-model=\"selectedOperatorOrderBy\" :placeholder=\"$t(\'form.select.operator\')\">\n                    <el-option v-for=\"ope in orders\" :key=\"ope\" :label=\"ope\" :value=\"ope\">\n                    </el-option>\n                </el-select>\n            </el-col>\n        </el-row>\n        <el-row class=\"el-row-modal-grey\">\n            <el-col>\n                </br>\n                <el-button size=\"small\" class=\"el-apply-button float-right\" @click=\"aceptedAddOrderByParameter\">\n                    {{ $t(\"button.apply\") }}</el-button>\n                <el-button size=\"small\" class=\"el-cancel-button float-right\" @click=\"dialogAddOrderByVisible = false\">\n                    {{ $t(\"button.cancel\") }}</el-button>\n            </el-col>\n        </el-row>\n    </el-dialog>\n\n\n</div>\n','vm.vueconfig = {\n   el: document.getElementById(vm.id).querySelector(\'vuetemplate .appgadget\'),\n   data: {\n      typeGadget: \'withWizard\', //[\'withWizard\',\'noWizard\',\'searchOnly\']\n      hideIdColumn: false, // show or hide id column\n      initialEntity: \"\" , //variable that initializes the entity with the value assigned to it\n\n      showTable: false,\n      showSelectOntology: true,\n      showWizard: false,\n      disabledWizard: true,\n      idPath: \"\",\n      ontologies: [],\n      ontologyFieldsAndDesc: {},\n      recordSelected: \"\",\n      selectedOntology: \"\",\n      selectedOntologySchema: {},\n\n      dialogDeleteVisible: false, //hide show dialogs\n      dialogEditVisible: false,\n      dialogCreateVisible: false,\n      dialogShowVisible: false,\n      dialogOptionsColumnsVisible: false,\n      dialogAddSelectVisible: false,\n      dialogDownloadVisible:false,\n      idelem:vm.id,\n      executeSearch:false,\n      showMagnifyingGlass: true,\n      jEditor: {},\n      jShowEditor: {},\n      tableHeight: 100,\n      resizeObserver: {},\n      selectWizard: [],\n      selectWizardOptions: [],\n      orderByWizard: [],\n      orderByWizardOptions: [],\n      dialogAddOrderByVisible: false,\n      limitWizard: 100, // limit of records in the search for initialize at another value change on resetwizard too\n      offsetWizard: 0, //offset records in the search\n      whereCondition: \'\',\n      uniqueID: \'\', // save path of id\n      selectedParametereWhere: \'\',\n      selectedOperatorWhere: \'\',\n      selectedParametereOrderBy: \'\',\n      selectedOperatorOrderBy: \'\',\n      inputValueWhere: \'\',\n      editTitle: \'\',\n      showTitle: \'\',\n      downloadType:\'\',\n      visibleColumns: [], // list of visible columns\n      columnsParams: [],\n      searchString: \'\', // text for local search\n      formOptions: {\n         forms: []\n      },\n      orders: [\'ASC\', \'DESC\'],\n      operators: [\'=\', \'>\', \'<\', \'>=\', \'<=\', \'!=\'],\n      ds: [],\n      columns: [],\n      tableData: [],\n      platformhost: __env.endpointControlPanel\n   },\n   methods: {\n      drawVueComponent: function (newData, oldData) {\n         //This will be call on new data\n      },\n      resizeEvent: function () {\n         //Resize event\n\n      },\n      destroyVueComponent: function () {\n         vm.vueapp.$destroy();\n      },\n      receiveValue: function (data) {\n         //data received from datalink\n      },\n      //function that initially reads the entities\n      loadEntities: function (search, loading) {\n         var that = this;\n         vm.getEntities().then(function (data) {\n            that.ontologies = data.data.map(function (obj) {\n               return {\n                  id: obj.id,\n                  identification: obj.identification\n               }\n            });\n\n            if(that.initialEntity!=null && that.initialEntity!==\"\"){\n               if (that.ontologies.some(e => e.identification === that.initialEntity)) {\n                     that.selectedOntology = that.initialEntity;\n                     that.onChangeEntity(that.selectedOntology);\n                     that.showSelectOntology = true;\n                     return;\n                  } else {\n                     that.$notify({\n                        message: that.$t(\'error.message.ontology\'),\n                        type: \'error\'\n                     });\n                  }\n            }\n            var urlparam = urlParamService.generateFiltersForGadgetId(vm.id);\n            if (typeof urlparam !== \'undefined\' && urlparam !== null && urlparam.length > 0) {\n               if (urlparam[0].exp != null) {\n                  var urlontology = urlparam[0].exp.replace(/\"/g, \'\');\n                  if (that.ontologies.some(e => e.identification === urlontology)) {\n                     that.selectedOntology = urlontology;\n                     that.onChangeEntity(that.selectedOntology);\n                     that.showSelectOntology = true;\n                     return;\n                  } else {\n                     that.$notify({\n                        message: that.$t(\'error.message.ontology\'),\n                        type: \'error\'\n                     });\n                  }\n               }\n            } else {\n               that.showSelectOntology = false;\n            }\n\n         })\n      },\n      //function that obtains the information of the selected ontology\n      loadHeadTable: function () {\n         var that = this;\n         if (this.ontologies != null && this.ontologies.length > 0) {\n            for (var i = 0; i < this.ontologies.length; i++) {\n               if (this.ontologies[i].identification === this.selectedOntology) {\n                  vm.crudGetEntityInfo(this.ontologies[i].id).then(function (data) {\n                     that.uniqueID = data.data.uniqueId;\n                     that.selectedOntologySchema = that.changeDescriptionForTitle(data.data.jsonSchema);\n                  });\n                  break;\n               }\n            }\n         }\n         vm.getOntologyFieldsAndDesc(this.selectedOntology).then(function (data) {\n            that.ontologyFieldsAndDesc = data.data;\n            that.loadData();\n         })\n      },\n      //function that gets the data and loads it to be displayed in the table\n      //difference if it is an initial query or the search button is pressed\n      loadData: function (fromSearch) {\n         var that = this;\n         that.showTable = false;\n         var selectStatement = {};\n         if (typeof fromSearch == \'undefined\' || fromSearch == null || fromSearch == false) {\n            selectStatement = {\n               ontology: this.selectedOntology,\n               columns: [],\n               where: [],\n               orderBy: [],\n               limit: this.limitWizard,\n               offset: this.offsetWizard\n            };\n         } else {\n            selectStatement = {\n               ontology: this.selectedOntology,\n               columns: [],\n               where: this.mapArrayToObjects(this.selectWizard),\n               orderBy: this.mapArrayToObjects(this.orderByWizard),\n               limit: this.limitWizard,\n               offset: this.offsetWizard\n            };\n         }\n         vm.crudQueryParams(selectStatement).then(function (data) {\n            that.showTable = true;\n            that.disabledWizard = false;\n            //create columns from that.ontologyFieldsAndDesc\n            var keys = Object.keys(that.ontologyFieldsAndDesc);\n\n            //validate error from data\n            if (typeof data.data.error !== \'undefined\') {\n               that.$notify({\n                  message: that.$t(\'error.message.querying.the.data\'),\n                  type: \'error\'\n               });\n               return {};\n            }\n            if (keys != null && keys.length > 0) {\n               if (typeof fromSearch != \'undefined\' && fromSearch != null && fromSearch) {\n                  var index = that.columns.findIndex(function (elem) {\n                     return elem.prop === that.uniqueID\n                  });\n                  if (index < 0) {\n                     that.idPath = that.uniqueID;\n                     that.columns.push({\n                        prop: that.uniqueID,\n                        label: \"id\"\n                     });\n\n                  }\n                  that.tableData = data.data.map(function (dat) {\n                     var refinedData = {};\n                     for (var i = 0; i < that.columns.length; i++) {\n                        let path = that.columns[i].prop.split(\'.\');\n                           try {\n                                  refinedData[that.columns[i].prop] = path.reduce((a, v) => a[v], dat);              \n                              } catch (error) {\n                                   refinedData[that.columns[i].prop] = null; \n                              }                     }\n\n                     return refinedData;\n                  })\n               } else {\n                  that.columns = [];\n\n                  var index = keys.findIndex(function (elem) {\n                     return elem === that.uniqueID\n                  });\n                  if (index > -1) {\n                     keys.splice(index, 1);\n                  }\n                  that.idPath = that.uniqueID;\n                  that.columns.push({\n                     prop: that.uniqueID,\n                     label: \"id\"\n                  });\n                  keys = keys.sort(that.orderKeys);\n                  //initial construction of table columns\n                  for (var i = 0; i < keys.length; i++) {\n                     var description = that.ontologyFieldsAndDesc[keys[i]].description;\n                     if (description == null || typeof description == undefined || description.length == 0) {\n                        description = that.ontologyFieldsAndDesc[keys[i]].path;\n                     }\n                     description = that.$t(description) || description;\n                     that.columns.push({\n                        prop: that.ontologyFieldsAndDesc[keys[i]].path,\n                        thetype: that.ontologyFieldsAndDesc[keys[i]].type,\n                        label: description,\n                        minWidth: 100,\n                        sortable: \'custom\'\n                     });\n\n                  }\n\n                  //mapping the data to display\n                  that.tableData = data.data.map(function (dat) {\n                     var refinedData = {};\n                     for (var i = 0; i < that.columns.length; i++) {\n                        if(typeof that.columns[i].prop!=\'undefined\' && that.columns[i].prop!=null){\n                           let path = that.columns[i].prop.split(\'.\');\n                             try {\n                                  refinedData[that.columns[i].prop] = path.reduce((a, v) => a[v], dat);              \n                              } catch (error) {\n                                   refinedData[that.columns[i].prop] = null; \n                              }                        }\n                     }\n\n                     return refinedData;\n                  })\n               }\n               //hide or show id columns\n               if (that.hideIdColumn) {\n\n                  var index = that.columns.findIndex(function (elem) {\n                     return elem.label === \'id\'\n                  });\n                  if (index > -1) {\n                     that.columns.splice(index, 1);\n                  }\n\n               }\n               if (that.visibleColumns.length == 0 && that.columns.length > 0) {\n                  that.visibleColumns = Array.from(that.columns);\n                  that.columnsParams = Array.from(that.columns);\n                  that.visibleColumns.forEach(function (element) {\n                     element.visible = true;\n                  });\n               }\n\n\n            }\n         })\n      },\n      //function that is executed when the edition of a record is opened\n      openEdit: function () {\n         var that = this;\n         vm.crudFindById(this.recordSelected, this.selectedOntology).then(function (data) {\n            delete data.data[0]._id;\n            delete data.data[0].contextData;\n            if (typeof that.jEditor.destroy == \'function\') that.jEditor.destroy();\n            that.jEditor = new JSONEditor(document.getElementsByClassName(vm.id+\' editor_edit_holder\')[0], {\n               schema: JSON.parse(that.selectedOntologySchema),\n               startval: data.data[0],\n               theme: \'bootstrap3\',\n               iconlib: \'fontawesome4\',\n               disable_properties: true,\n               disable_edit_json: true,\n               disable_collapse: true,\n               disable_array_reorder: true,\n               disable_array_delete_all_rows: true,\n               disable_array_delete_last_row: true,\n               show_errors: \'change\'\n            });\n         })\n      },\n      //function that is executed when the detail of a record is opened\n      openShow: function () {\n         var that = this;\n         vm.crudFindById(this.recordSelected, this.selectedOntology).then(function (data) {\n            delete data.data[0]._id;\n            delete data.data[0].contextData;\n            if (typeof that.jShowEditor.destroy == \'function\') that.jShowEditor.destroy();\n            that.jShowEditor = new JSONEditor(document.getElementsByClassName(vm.id+\' editor_show_holder\')[0], {\n         