that.initialEntity;\n                            that.importdisabled = false;\n                            that.downloaddisabled = false;\n                            that.uploaddisabled = false;\n                            that.showSelect = false;\n                            that.showEntityName = true;\n                            that.onChangeOntology( that.initialEntity);                        } else {\n                            that.msgerr = that.$t(\'error.message.ontology\');                      \n                            that.dialogCreateVisible = true;\n                        }\n                        that.showSelectOntology=true;\n                        return;\n                }\n\n                var urlparam = urlParamService.generateFiltersForGadgetId(vm.id);\n                if(typeof urlparam!== \'undefined\' && urlparam!==null && urlparam.length>0){             \n                    if(urlparam[0].exp!=null){\n                        var urlontology = urlparam[0].exp.replace(/\"/g,\'\');\n                        if(that.ontologies.some(e => e.identification === urlontology)) {\n                            that.selectedOntology = urlontology;\n                            that.importdisabled = false;\n                            that.downloaddisabled = false;\n                            that.uploaddisabled = false;\n                            that.showSelect = false;\n                            that.showEntityName = true;\n                            that.onChangeOntology( that.initialEntity);                        } else {\n                            that.msgerr = that.$t(\'error.message.ontology\');                      \n                            that.dialogCreateVisible = true;\n                        }\n                        that.showSelectOntology=true;\n                        return;\n                    }\n                }else{\n                    that.showSelectOntology=false;\n                }\n            })\n        },\n        getCSVSchema:function() {\n            var that = this;\n            vm.isComplexSchema(this.selectedOntology).then(function(data){\n                if(data.data.message == \'ok\'){\n                    vm.downloadEntitySchemaCsv(that.selectedOntology);\n                } else{\n                that.msgerr = that.$t(data.data.message);               \n                that.dialogCreateVisible = true;\n                }\n            });\n            that.dialogDownloadOptions = false;\n        },\n        getJSONSchema: function() {\n            var that = this;\n            vm.downloadEntitySchemaJson(that.selectedOntology);\n            that.dialogDownloadOptions = false;\n        },\n        submitUpload:function() {\n            this.$refs.upload.submit();\n        },\n         onChangeOntology(value) {\n            this.selectedOntology = value;\n            this.urlimport = \"/dashboardengine/api/insertDataEntity/\" + value;  \n            this.importdisabled = false;\n            this.downloaddisabled = false;\n            this.uploaddisabled = false;\n        },\n        beforeCSVUpload:function(file) { \n            const isLt2M = file.size / 1024 < 2000;\n            if(!isLt2M) {\n                this.$alert(this.$t(\'error.message.exceed\'), \'Warning\', {\n                    confirmButtonText: \'OK\',\n                    type: \'warning\'\n                });\n                return false;\n            }\n        },\n        handleError:function(err, file, fileList){\n            var jsonerr;\n            \n            try{\n                jsonerr = JSON.parse(err.message);\n                this.msgerr = this.$t(jsonerr.message);\n                if(jsonerr.detail != \'\'){\n                    this.detailerr = JSON.stringify(jsonerr.detail);\n                    this.showDetailBtn = true;\n                }   \n            } catch(objError){\n                this.msgerr = err.name + \" \" + err.status;\n                this.detailerr = e