INSERT INTO `gadget_template_type` (`id`, `created_at`, `headerlibs`, `identification`, `template`, `templatejs`, `updated_at`) VALUES ('angularJS','2026-07-05 18:39:21','','AngularJS','<!-- Write your HTML <div></div> and CSS <style></style> here -->\n<!--Focus here and F11 or F10 to full screen editor-->','//Write your controller (JS code) code here\n\n//Focus here and F11 or F10 to full screen editor\n\n//This function will be call once to init components\nvm.initLiveComponent = function(){\n\n};\n\n//This function will be call when data change. On first execution oldData will be null\nvm.drawLiveComponent = function(newData, oldData){\n\n};\n\n//This function will be call on element resize\nvm.resizeEvent = function(){\n\n}\n\n//This function will be call when element is destroyed\nvm.destroyLiveComponent = function(){\n\n};\n\n//This function will be call when receiving a value from vm.sendValue(idGadgetTarget,data)\nvm.receiveValue = function(data){\n\n};','2026-07-05 18:39:21'),('reactJS','2026-07-05 18:39:21','<script src=\"/controlpanel/static/vendor/react/react.production.min.js\" crossorigin></script>\n<script src=\"/controlpanel/static/vendor/react/react-dom.production.min.js\" crossorigin></script>','ReactJS','<!-- Write your React CSS Style Here \n<!--Focus here and F11 or F10 to full screen editor-->','//Write your controller (JS code) code here\n\n//Focus here and F11 or F10 to full screen editor\n\n//This function will be call for render the React Gadget\nfunction GadgetComponent(props) {\n    const ds = props.ds;\n    return React.createElement(\"div\", null, null);\n}\n\n//This function will be call on init event and when data arrives to the React Gadget\nvm.renderReactGadget = function(ds, old_ds){\n  ReactDOM.render(\n      React.createElement(GadgetComponent, { ds: ds || [] }), document.querySelector(\'#\' + vm.id + \' reacttemplate\' + \' .rootapp\')\n  );\n}\n\n//This function will be call in destroy event of React Gadget\nvm.destroyReactGadget = function(){\n\n}\n\n//This function will be call when receiving a value from vm.sendValue(idGadgetTarget,data)\nvm.receiveValue = function(data){\n\n};','2026-07-05 18:39:21'),('vueJS','2026-07-05 18:39:21','','VueJS','<!--Focus here and F11 or F10 to full screen editor-->\n<!-- Write your CSS <style></style> here -->\n<div class=\"gadget-app\">\n<!-- Write your HTML <div></div> here -->\n</div>','//Write your Vue JSON controller code here\n\n//Focus here and F11 to full screen editor\n\n//This function will be call once to init components\n\nvm.vueconfig = {\n	el: document.getElementById(vm.id).querySelector(\'vuetemplate  .gadget-app\'),\n	data:{\n		ds:[]\n	},\n	methods:{\n		drawVueComponent: function(newData,oldData){\n			//This will be call on new data\n		},\n		resizeEvent: function(){\n			//Resize event\n		},\n		destroyVueComponent: function(){\n			vm.vueapp.$destroy();\n		},\n		receiveValue: function(data){\n			//data received from datalink\n		},\n		sendValue: vm.sendValue,\n		sendFilter: vm.sendFilter\n	}\n}\n\n//Init Vue app\nvm.vueapp = new Vue(vm.vueconfig);\n','2026-07-05 18:39:21'),('vueJSODS','2026-07-05 18:39:21','','VueJS+ODS','<!--Focus here and F11 or F10 to full screen editor-->\n<!-- Write your CSS <style></style> here -->\n<div class=\"gadget-app\">\n<!-- Write your HTML <div></div> here -->\n</div>','//Write your Vue with ODS JSON controller code here\n\n//Focus here and F11 or F10 to full screen editor\n\n//This function will be call once to init components\n\nvm.vueconfig = {\n	el: document.getElementById(vm.id).querySelector(\'vuetemplate  .gadget-app\'),\n	data:{\n		ds:[]\n	},\n	methods:{\n		drawVueComponent: function(newData,oldData){\n			//This will be call on new data\n		},\n		resizeEvent: function(){\n			//Resize event\n		},\n		destroyVueComponent: function(){\n			vm.vueapp.$destroy();\n		},\n		receiveValue: function(data){\n			//data received from datalink\n		},\n		sendValue: vm.sendValue,\n		sendFilter: vm.sendFilter\n	}\n}\n\n//Init Vue app\nvm.vueapp = new Vue(vm.vueconfig);\n','2026-07-05 18:39:21');
